// ─── Bridge 9 — Add/Subtract Same Denominator ─────────────────────────
function generateBridge9Question() {
  const isAdd = Math.random() < 0.6;
  const c = bridge_randInt(3, 12);
  let a, b, num;
  if (isAdd) {
    a = bridge_randInt(1, c - 1);
    b = bridge_randInt(1, c);
    num = a + b;
  } else {
    a = bridge_randInt(2, c - 1);
    b = bridge_randInt(1, a - 1);
    num = a - b;
  }
  const g = bridge_gcd(num, c);
  const sn = num / g,
    sd = c / g;
  const op = isAdd ? '+' : '−';
  const prompt = [{
    frac: [a, c]
  }, `  ${op}  `, {
    frac: [b, c]
  }];
  const answerKey = `frac:${sn}/${sd}`;
  const dist = [];
  const tryAdd = (n, d) => {
    if (!Number.isInteger(n) || !Number.isInteger(d) || n <= 0 || d <= 0) return;
    const k = `frac:${n}/${d}`;
    if (k === answerKey || dist.find(x => x.key === k)) return;
    dist.push({
      seg: [{
        frac: [n, d]
      }],
      key: k
    });
  };
  tryAdd(num, c + c); // added denominators (classic)
  if (num !== sn || c !== sd) tryAdd(num, c); // unsimplified
  tryAdd(isAdd ? a - b : a + b, c); // wrong operation
  tryAdd(a * b, c); // multiplied
  if (sn > 1) tryAdd(sn - 1, sd);
  const {
    options,
    correctIndex
  } = bridge_buildSegOptions([{
    frac: [sn, sd]
  }], answerKey, dist);
  const explanation = num !== sn ? [`Same denominator. ${a} ${op} ${b} = ${num}. So  `, {
    frac: [a, c]
  }, ` ${op} `, {
    frac: [b, c]
  }, ' = ', {
    frac: [num, c]
  }, ' = ', {
    frac: [sn, sd]
  }, '.'] : [`Same denominator. ${a} ${op} ${b} = ${num}. So  `, {
    frac: [a, c]
  }, ` ${op} `, {
    frac: [b, c]
  }, ' = ', {
    frac: [sn, sd]
  }, '.'];
  return {
    prompt,
    options,
    correctIndex,
    explanation
  };
}

// ─── Bridge 10 — LCM Hunt ─────────────────────────────────────────────
function generateBridge10Question() {
  const tier = Math.random();
  let m, n;
  if (tier < 0.3) {
    m = bridge_randInt(2, 6);
    n = bridge_randInt(2, 6);
  } else if (tier < 0.7) {
    m = bridge_randInt(3, 12);
    n = bridge_randInt(3, 12);
  } else {
    m = bridge_randInt(4, 20);
    n = bridge_randInt(4, 20);
  }
  if (m === n) n = n % 12 + 2; // make different
  const hcf = bridge_gcd(m, n);
  const lcm = m * n / hcf;
  const candidates = [m * n, hcf, Math.max(m, n), Math.min(m, n), lcm + Math.min(m, n), lcm - Math.min(m, n)];
  const {
    options,
    correctIndex
  } = bridge_buildOptions(lcm, candidates);
  const prompt = `Find  LCM(${m},  ${n})`;
  const explanation = hcf > 1 ? `${m} × ${n} = ${m * n}.  HCF(${m}, ${n}) = ${hcf}.  LCM = product ÷ HCF = ${m * n} ÷ ${hcf} = ${lcm}.` : `${m} and ${n} share no common factor (HCF = 1), so LCM = ${m} × ${n} = ${lcm}.`;
  return {
    prompt,
    options,
    correctIndex,
    explanation
  };
}

// ─── Bridge 11 — Add/Subtract Different Denominators ──────────────────
function generateBridge11Question() {
  let f1,
    f2,
    attempts = 0;
  while (attempts++ < 30) {
    f1 = bridge_pickSimplestFraction(8);
    f2 = bridge_pickSimplestFraction(8);
    if (f1.q !== f2.q) break;
  }
  if (f1.q === f2.q) f2 = {
    p: 1,
    q: f1.q + 1
  };
  const isAdd = Math.random() < 0.6;
  const lcm = f1.q * f2.q / bridge_gcd(f1.q, f2.q);
  const k1 = lcm / f1.q,
    k2 = lcm / f2.q;
  const a1 = f1.p * k1,
    a2 = f2.p * k2;
  let num;
  if (isAdd) num = a1 + a2;else {
    num = a1 - a2;
    if (num <= 0) return generateBridge11Question();
  }
  const g = bridge_gcd(num, lcm);
  const sn = num / g,
    sd = lcm / g;
  const op = isAdd ? '+' : '−';
  const prompt = [{
    frac: [f1.p, f1.q]
  }, `  ${op}  `, {
    frac: [f2.p, f2.q]
  }];
  const answerKey = `frac:${sn}/${sd}`;
  const dist = [];
  const tryAdd = (n, d) => {
    if (!Number.isInteger(n) || !Number.isInteger(d) || n <= 0 || d <= 0) return;
    const k = `frac:${n}/${d}`;
    if (k === answerKey || dist.find(x => x.key === k)) return;
    dist.push({
      seg: [{
        frac: [n, d]
      }],
      key: k
    });
  };
  // Distractors:
  tryAdd(isAdd ? f1.p + f2.p : Math.abs(f1.p - f2.p), f1.q + f2.q); // added across (classic mistake)
  if (sn !== num || sd !== lcm) tryAdd(num, lcm); // unsimplified
  tryAdd(f1.p * f2.q + f2.p * f1.q, f1.q * f2.q); // used product as common denom (also valid!), different presentation
  tryAdd(isAdd ? f1.p + f2.p : Math.abs(f1.p - f2.p), Math.max(f1.q, f2.q)); // kept original denom
  if (sn > 1) tryAdd(sn - 1, sd);
  const {
    options,
    correctIndex
  } = bridge_buildSegOptions([{
    frac: [sn, sd]
  }], answerKey, dist);
  const explanation = [`LCM(${f1.q}, ${f2.q}) = ${lcm}.  Rewrite: `, {
    frac: [a1, lcm]
  }, ` ${op} `, {
    frac: [a2, lcm]
  }, ' = ', {
    frac: [num, lcm]
  }, num !== sn ? [' = ', {
    frac: [sn, sd]
  }] : '', '.'];
  return {
    prompt,
    options,
    correctIndex,
    explanation
  };
}

// ─── Bridge 12 — Add/Subtract Mixed Numbers ───────────────────────────
function generateBridge12Question() {
  const w1 = bridge_randInt(1, 4);
  const f1 = bridge_pickSimplestFraction(6);
  const w2 = bridge_randInt(1, 4);
  const f2 = bridge_pickSimplestFraction(6);
  const isAdd = Math.random() < 0.6;
  const a = w1 * f1.q + f1.p,
    b = f1.q;
  const c = w2 * f2.q + f2.p,
    d = f2.q;
  const lcm = b * d / bridge_gcd(b, d);
  const k1 = lcm / b,
    k2 = lcm / d;
  const aa = a * k1,
    cc = c * k2;
  let num;
  if (isAdd) num = aa + cc;else {
    num = aa - cc;
    if (num <= 0) return generateBridge12Question();
  }
  const g = bridge_gcd(num, lcm);
  const sn = num / g,
    sd = lcm / g;
  const op = isAdd ? '+' : '−';
  const prompt = [w1, {
    frac: [f1.p, f1.q]
  }, `  ${op}  `, w2, {
    frac: [f2.p, f2.q]
  }];
  const answerKey = `frac:${sn}/${sd}`;
  const dist = [];
  const tryAdd = (n, dd) => {
    if (!Number.isInteger(n) || !Number.isInteger(dd) || n <= 0 || dd <= 0) return;
    const k = `frac:${n}/${dd}`;
    if (k === answerKey || dist.find(x => x.key === k)) return;
    dist.push({
      seg: [{
        frac: [n, dd]
      }],
      key: k
    });
  };
  tryAdd(num, lcm); // unsimplified
  if (isAdd) tryAdd(w1 + w2, 1); // added wholes only
  if (isAdd) tryAdd(f1.p + f2.p, f1.q + f2.q); // ignored wholes, added fractions across
  if (!isAdd) tryAdd(Math.abs(w1 - w2), 1);
  if (sn > 1) tryAdd(sn - 1, sd);
  const {
    options,
    correctIndex
  } = bridge_buildSegOptions([{
    frac: [sn, sd]
  }], answerKey, dist);
  const explanation = [`Convert: `, w1, {
    frac: [f1.p, f1.q]
  }, ' = ', {
    frac: [a, b]
  }, ',  ', w2, {
    frac: [f2.p, f2.q]
  }, ' = ', {
    frac: [c, d]
  }, `.  LCM(${b}, ${d}) = ${lcm}.  `, {
    frac: [aa, lcm]
  }, ` ${op} `, {
    frac: [cc, lcm]
  }, ' = ', {
    frac: [num, lcm]
  }, num !== sn ? [' = ', {
    frac: [sn, sd]
  }] : '', '.'];
  return {
    prompt,
    options,
    correctIndex,
    explanation
  };
}
