// ─── Bridge 13 — Reciprocals ──────────────────────────────────────────
function generateBridge13Question() {
  const isFraction = Math.random() < 0.6;
  if (isFraction) {
    const {
      p,
      q
    } = bridge_pickSimplestFraction(9);
    const prompt = ['What is the reciprocal of  ', {
      frac: [p, q]
    }, '?'];
    const answerKey = `frac:${q}/${p}`;
    const dist = [];
    const tryAdd = (n, d) => {
      if (!Number.isInteger(n) || !Number.isInteger(d) || n <= 0 || d <= 0) return;
      const k = `frac:${n}/${d}`;
      if (k === answerKey || dist.find(x => x.key === k)) return;
      dist.push({
        seg: [{
          frac: [n, d]
        }],
        key: k
      });
    };
    tryAdd(p, q); // same fraction (trap — students sometimes don't flip)
    tryAdd(q + 1, p);
    tryAdd(q, p + 1);
    if (q > 1) tryAdd(q - 1, p);
    const {
      options,
      correctIndex
    } = bridge_buildSegOptions([{
      frac: [q, p]
    }], answerKey, dist);
    return {
      prompt,
      options,
      correctIndex,
      explanation: ['Flip the fraction upside down: ', {
        frac: [p, q]
      }, ' → ', {
        frac: [q, p]
      }, '.']
    };
  } else {
    const w = bridge_randInt(2, 12);
    const prompt = `What is the reciprocal of  ${w}?`;
    const answerKey = `frac:1/${w}`;
    const dist = [];
    const tryAdd = (n, d) => {
      if (!Number.isInteger(n) || !Number.isInteger(d) || n <= 0 || d <= 0) return;
      const k = `frac:${n}/${d}`;
      if (k === answerKey || dist.find(x => x.key === k)) return;
      dist.push({
        seg: [{
          frac: [n, d]
        }],
        key: k
      });
    };
    tryAdd(w, 1);
    tryAdd(w, w);
    tryAdd(1, w + 1);
    tryAdd(2, w);
    const {
      options,
      correctIndex
    } = bridge_buildSegOptions([{
      frac: [1, w]
    }], answerKey, dist);
    return {
      prompt,
      options,
      correctIndex,
      explanation: [`Treat ${w} as `, {
        frac: [w, 1]
      }, '.  Flip it: ', {
        frac: [1, w]
      }, '.']
    };
  }
}

// ─── Bridge 14 — Divide Fractions (Keep-Change-Flip) ──────────────────
function generateBridge14Question() {
  const v = Math.random();
  if (v < 0.5) {
    // f1 ÷ f2
    const f1 = bridge_pickSimplestFraction(7);
    const f2 = bridge_pickSimplestFraction(7);
    const num = f1.p * f2.q;
    const den = f1.q * f2.p;
    const g = bridge_gcd(num, den);
    const sn = num / g,
      sd = den / g;
    const prompt = [{
      frac: [f1.p, f1.q]
    }, '  ÷  ', {
      frac: [f2.p, f2.q]
    }];
    const answerKey = `frac:${sn}/${sd}`;
    const dist = [];
    const tryAdd = (n, d) => {
      if (!Number.isInteger(n) || !Number.isInteger(d) || n <= 0 || d <= 0) return;
      const k = `frac:${n}/${d}`;
      if (k === answerKey || dist.find(x => x.key === k)) return;
      dist.push({
        seg: [{
          frac: [n, d]
        }],
        key: k
      });
    };
    tryAdd(f1.p * f2.p, f1.q * f2.q); // multiplied without flipping (classic mistake)
    tryAdd(f2.q * f1.p, f2.p * f1.q); // flipped first instead of second (same result accidentally — covered above)
    if (num !== sn || den !== sd) tryAdd(num, den); // unsimplified
    tryAdd(sd, sn); // flipped answer
    const {
      options,
      correctIndex
    } = bridge_buildSegOptions([{
      frac: [sn, sd]
    }], answerKey, dist);
    return {
      prompt,
      options,
      correctIndex,
      explanation: ['Keep the first, flip the second, multiply: ', {
        frac: [f1.p, f1.q]
      }, ' × ', {
        frac: [f2.q, f2.p]
      }, ' = ', {
        frac: [num, den]
      }, num !== sn ? [' = ', {
        frac: [sn, sd]
      }] : '', '.']
    };
  } else if (v < 0.75) {
    // mixed ÷ mixed (or mixed ÷ fraction)
    const w1 = bridge_randInt(1, 4);
    const f1 = bridge_pickSimplestFraction(5);
    const w2 = bridge_randInt(1, 4);
    const f2 = bridge_pickSimplestFraction(5);
    const a = w1 * f1.q + f1.p,
      b = f1.q;
    const c = w2 * f2.q + f2.p,
      d = f2.q;
    const num = a * d;
    const den = b * c;
    const g = bridge_gcd(num, den);
    const sn = num / g,
      sd = den / g;
    const prompt = [w1, {
      frac: [f1.p, f1.q]
    }, '  ÷  ', w2, {
      frac: [f2.p, f2.q]
    }];
    const answerKey = `frac:${sn}/${sd}`;
    const dist = [];
    const tryAdd = (n, dd) => {
      if (!Number.isInteger(n) || !Number.isInteger(dd) || n <= 0 || dd <= 0) return;
      const k = `frac:${n}/${dd}`;
      if (k === answerKey || dist.find(x => x.key === k)) return;
      dist.push({
        seg: [{
          frac: [n, dd]
        }],
        key: k
      });
    };
    tryAdd(a * c, b * d); // multiplied without flipping
    tryAdd(num, den); // unsimplified
    tryAdd(w1, w2); // divided wholes only
    tryAdd(b * d, a * c); // flipped result
    const {
      options,
      correctIndex
    } = bridge_buildSegOptions([{
      frac: [sn, sd]
    }], answerKey, dist);
    return {
      prompt,
      options,
      correctIndex,
      explanation: ['Convert: ', w1, {
        frac: [f1.p, f1.q]
      }, ' = ', {
        frac: [a, b]
      }, ',  ', w2, {
        frac: [f2.p, f2.q]
      }, ' = ', {
        frac: [c, d]
      }, '.  Flip second and multiply: ', {
        frac: [a, b]
      }, ' × ', {
        frac: [d, c]
      }, ' = ', {
        frac: [num, den]
      }, num !== sn ? [' = ', {
        frac: [sn, sd]
      }] : '', '.']
    };
  } else {
    // whole ÷ fraction or fraction ÷ whole
    const f = bridge_pickSimplestFraction(7);
    const w = bridge_randInt(2, 9);
    const wholeFirst = Math.random() < 0.5;
    let num, den;
    if (wholeFirst) {
      // w ÷ p/q = w × q/p = wq/p
      num = w * f.q;
      den = f.p;
    } else {
      // p/q ÷ w = p/q × 1/w = p/(qw)
      num = f.p;
      den = f.q * w;
    }
    const g = bridge_gcd(num, den);
    const sn = num / g,
      sd = den / g;
    const prompt = wholeFirst ? [String(w), '  ÷  ', {
      frac: [f.p, f.q]
    }] : [{
      frac: [f.p, f.q]
    }, '  ÷  ', String(w)];
    const answerKey = `frac:${sn}/${sd}`;
    const dist = [];
    const tryAdd = (n, d) => {
      if (!Number.isInteger(n) || !Number.isInteger(d) || n <= 0 || d <= 0) return;
      const k = `frac:${n}/${d}`;
      if (k === answerKey || dist.find(x => x.key === k)) return;
      dist.push({
        seg: [{
          frac: [n, d]
        }],
        key: k
      });
    };
    if (wholeFirst) {
      tryAdd(w * f.p, f.q); // multiplied without flipping
      tryAdd(f.q, w * f.p); // flipped result
    } else {
      tryAdd(f.p * w, f.q); // multiplied instead of dividing
      tryAdd(f.q, f.p * w);
    }
    if (num !== sn || den !== sd) tryAdd(num, den);
    const {
      options,
      correctIndex
    } = bridge_buildSegOptions([{
      frac: [sn, sd]
    }], answerKey, dist);
    const explanation = wholeFirst ? [`Treat ${w} as `, {
      frac: [w, 1]
    }, '.  Flip second: ', {
      frac: [f.q, f.p]
    }, '.  Multiply: ', {
      frac: [w * f.q, f.p]
    }, num !== sn ? [' = ', {
      frac: [sn, sd]
    }] : '', '.'] : [`Treat ${w} as `, {
      frac: [w, 1]
    }, '.  Flip second: ', {
      frac: [1, w]
    }, '.  Multiply: ', {
      frac: [f.p, f.q * w]
    }, num !== sn ? [' = ', {
      frac: [sn, sd]
    }] : '', '.'];
    return {
      prompt,
      options,
      correctIndex,
      explanation
    };
  }
}
