// ─── Bridge 16 — "Fraction OF a Number" / "What fraction is M of N" ───
function generateBridge16Question() {
  const v = Math.random();
  if (v < 0.6) {
    // a/b of N = a/b × N (chosen so result is a clean integer)
    const {
      p,
      q
    } = bridge_pickSimplestFraction(7);
    const k = bridge_randInt(2, 8);
    const N = q * k;
    const answer = p * k;
    const prompt = ['What is  ', {
      frac: [p, q]
    }, `  of  ${N}?`];
    const candidates = [q * k,
    // multiplied N by denominator (mistake: used wrong slot)
    N - answer,
    // the "other" portion (e.g., 1 - p/q)
    p + N,
    // added instead
    Math.round(N / q),
    // forgot numerator
    answer + 1, answer - 1];
    const {
      options,
      correctIndex
    } = bridge_buildOptions(answer, candidates);
    return {
      prompt,
      options,
      correctIndex,
      explanation: [{
        frac: [p, q]
      }, ` of ${N}  =  `, {
        frac: [p, q]
      }, ` × ${N}  =  ${p}×${N}÷${q}  =  ${p * N}÷${q}  =  ${answer}.`]
    };
  } else {
    // "What fraction of N is M?"  → M/N simplified
    const {
      p,
      q
    } = bridge_pickSimplestFraction(9);
    const k = bridge_randInt(2, 6);
    const N = q * k;
    const M = p * k;
    const prompt = `What fraction of  ${N}  is  ${M}?`;
    const answerKey = `frac:${p}/${q}`;
    const dist = [];
    const tryAdd = (n, d) => {
      if (!Number.isInteger(n) || !Number.isInteger(d) || n <= 0 || d <= 0) return;
      const ky = `frac:${n}/${d}`;
      if (ky === answerKey || dist.find(x => x.key === ky)) return;
      dist.push({
        seg: [{
          frac: [n, d]
        }],
        key: ky
      });
    };
    tryAdd(M, N); // unsimplified
    tryAdd(N, M); // flipped (asked the wrong way around)
    tryAdd(q, p); // simplest flipped
    if (p > 1) tryAdd(p - 1, q);
    if (q > p + 1) tryAdd(p, q - 1);
    const {
      options,
      correctIndex
    } = bridge_buildSegOptions([{
      frac: [p, q]
    }], answerKey, dist);
    return {
      prompt,
      options,
      correctIndex,
      explanation: [`Form the fraction `, {
        frac: [M, N]
      }, ` (the part over the whole), then simplify (HCF = ${k}): `, {
        frac: [p, q]
      }, '.']
    };
  }
}
