    setFinished(false);
    setStarted(true);
    setFeedback('');
    setIsCorrect(null);
    setRevealed(false);
    setCorrectAnswerDigits(null);
    setCorrectCarryDigits(null);
    setCorrectPPDigits(null);
    setCorrectPPCarries(null);
