/* ── Tatsavit1 Component ─────────────────────────────────
 * One MCQ at a time: Submit checks the answer, Explanation reveals a stepped
 * timeline via renderFeedback, Next advances. Finishes with a results summary.
 */
function Tatsavit1App({
  onBack,
  isGoalMode = false
}) {
  const [idx, setIdx] = useState(0);
  const [selected, setSelected] = useState(null);
  const [revealed, setRevealed] = useState(false);
  const [showSolve, setShowSolve] = useState(false);
  const [score, setScore] = useState(0);
  const [results, setResults] = useState([]);
  const [finished, setFinished] = useState(false);
  const [sessionGoal, setSessionGoal] = useState(isGoalMode ? 'speed' : 'standard');
  useEffect(() => {
    if (!isGoalMode) {
      setSessionGoal('standard');
    }
  }, [isGoalMode]);
  const total = TATSAVIT1_QUESTIONS.length;
  const q = TATSAVIT1_QUESTIONS[idx];
  const handleSubmit = () => {
    if (selected === null || revealed) return;
    const ok = selected === q.correctIndex;
    setRevealed(true);
    if (ok) setScore(s => s + 1);
    setResults(r => [...r, {
      question: q.prompt.replace(/\s+/g, ' ').slice(0, 90),
      userAnswer: q.options[selected],
      correctAnswer: q.options[q.correctIndex],
      correct: ok,
      time: 0
    }]);
  };
  const handleNext = () => {
    if (idx + 1 >= total) {
      setFinished(true);
      return;
    }
    setIdx(i => i + 1);
    setSelected(null);
    setRevealed(false);
    setShowSolve(false);
  };
  const handleRestart = () => {
    setIdx(0);
    setSelected(null);
    setRevealed(false);
    setShowSolve(false);
    setScore(0);
    setResults([]);
    setFinished(false);
  };
  const handleJumpPrev = () => {
    if (idx === 0) return;
    setIdx(i => i - 1);
    setSelected(null);
    setRevealed(false);
    setShowSolve(false);
  };
  if (finished) {
    return <QuizLayout title="Tatsavit 1 — Results" subtitle={`Score: ${score} / ${total} (${Math.round(100 * score / total)}%)`} onBack={onBack}>
        <div style={{
        textAlign: 'center',
        marginTop: 16,
        marginBottom: 16
      }}>
          <button className="submit-btn" onClick={handleRestart}>Play Again</button>
        </div>
        {results.length > 0 && <ResultsTable results={results} />}
      </QuizLayout>;
  }
  const isCorrect = selected === q.correctIndex;
  return <QuizLayout title="Tatsavit 1 — IGCSE Practice" subtitle={`Question ${idx + 1} of ${total} · ${q.section}`} onBack={onBack}>
      <div className="progress-pill center" style={{
      marginBottom: 12
    }}>
        Score: {score} · Answered: {results.length}
      </div>
      <div className="question-box" style={{
      whiteSpace: 'pre-wrap',
      textAlign: 'center',
      marginBottom: 16
    }}>
        <GlossaryText text={q.prompt || ''} />
      </div>
      <div className="options-list">
        {q.options.map((opt, i) => {
        const letter = String.fromCharCode(65 + i);
        const isSel = selected === i;
        const isRight = revealed && i === q.correctIndex;
        const isWrongPick = revealed && isSel && i !== q.correctIndex;
        let extra = '';
        if (isRight) extra = 'selected';else if (isSel && !revealed) extra = 'selected';
        return <label key={i} className={`option-card ${extra}`} style={{
          borderColor: isRight ? 'var(--clr-correct)' : isWrongPick ? 'var(--clr-wrong)' : undefined,
          background: isRight ? 'var(--clr-correct-bg)' : isWrongPick ? 'var(--clr-wrong-bg)' : undefined,
          opacity: revealed && !isRight && !isWrongPick ? 0.7 : 1
        }}>
              <input type="radio" name="tatsavit1" checked={isSel} onChange={() => !revealed && setSelected(i)} disabled={revealed} />
              <span><strong>{letter})</strong> {opt}</span>
            </label>;
      })}
      </div>
      {revealed && !showSolve && <div className={`feedback ${isCorrect ? 'correct' : 'wrong'}`} style={{
      marginTop: 14,
      textAlign: 'center'
    }}>
          {isCorrect ? '✓ Correct!' : `✗ Correct answer: ${String.fromCharCode(65 + q.correctIndex)}) ${q.options[q.correctIndex]}`}
        </div>}
      {showSolve && renderFeedback(q.explanation, false)}
      <div className="button-row" style={{
      marginTop: 16
    }}>
        {!revealed ? <button onClick={handleSubmit} disabled={selected === null}>Submit</button> : <button onClick={handleNext}>{idx + 1 >= total ? 'Finish Quiz' : 'Next →'}</button>}
        <button onClick={() => setShowSolve(s => !s)} style={{
        background: 'transparent',
        border: '1px solid var(--clr-accent)',
        color: 'var(--clr-accent)'
      }}>
          {showSolve ? 'Hide Explanation' : 'Explanation'}
        </button>
        {idx > 0 && !revealed && <button onClick={handleJumpPrev} style={{
        background: 'transparent',
        border: '1px solid var(--clr-text-soft)',
        color: 'var(--clr-text-soft)'
      }}>
            ← Previous
          </button>}
      </div>
    </QuizLayout>;
}

/**
 * RIYA_UNITS — Sequential, adaptive learning ladder for /riya.
 * Starts at basic arithmetic and climbs to the content of NIOS 311
 * Chapter 2 (Relations and Functions — I). Each unit pairs a brief
 * motivational lesson (two worked examples) with a short quiz.
 * A student must answer ≥ 4/5 questions correctly to advance;
 * otherwise the lesson replays with a gentle "let's review" note.
 * All problems are original practice items written for this ladder.
 */

/**
 * RiyaApp — adaptive lesson ladder for /riya.
 * For each unit in RIYA_UNITS, the student first sees a short lesson
 * (title + intro + two worked examples), then answers five MCQs.
 * Pass threshold: 4 of 5 correct. Passing advances to the next unit;
 * failing replays the lesson with a "let's review" banner.
 */
function RiyaApp({
  onBack,
  isGoalMode = false
}) {
  const [unitIdx, setUnitIdx] = useState(0);
  const [phase, setPhase] = useState('lesson'); // 'lesson' | 'quiz' | 'complete'
  const [quizIdx, setQuizIdx] = useState(0);
  const [selected, setSelected] = useState(null);
  const [revealed, setRevealed] = useState(false);
  const [showSolve, setShowSolve] = useState(false);
  const [totalCorrect, setTotalCorrect] = useState(0);
  const [totalAttempted, setTotalAttempted] = useState(0);
  const [reviewMode, setReviewMode] = useState(false); // shows "let's review" banner on replay
  const [unitResults, setUnitResults] = useState([]); // per-unit pass record, for summary
  // Permutation that maps display slot (A, B, C, D) → original option index.
  // Updated when the student advances to a new question so the correct
  // option is not always in position A.
  const [optionOrder, setOptionOrder] = useState([0, 1, 2, 3]);
  // Adaptive retry — activeIndices holds the subset of the unit's question
  // pool that is actually being asked in the current practice round. On a
  // fresh unit it's [0..n-1]; on a failed retry it shrinks to just the
  // questions the student got wrong.
  const [activeIndices, setActiveIndices] = useState(() => RIYA_UNITS[0].questions.map((_, i) => i));
  // Per-question state for the current practice round (indexed by position
  // within activeIndices): { selected, revealed }. Lets Back navigation
  // restore the student's earlier picks so they can review what they did.
  const [perQuestion, setPerQuestion] = useState([]);
  const [sessionGoal, setSessionGoal] = useState(isGoalMode ? 'speed' : 'standard');
  useEffect(() => {
    if (!isGoalMode) {
      setSessionGoal('standard');
    }
  }, [isGoalMode]);
  const totalUnits = RIYA_UNITS.length;
  const unit = RIYA_UNITS[unitIdx];
  const passThreshold = 4; // need >= 4 of 5 correct to advance on first pass

  // Current question in the active round
  const currentOrigIdx = activeIndices[quizIdx];
  const currentQuestion = unit && currentOrigIdx !== undefined ? unit.questions[currentOrigIdx] : null;

  // Reshuffle options whenever the displayed question changes (new unit,
  // new active-round index, or returning to quiz phase). Fisher–Yates.
  useEffect(() => {
    const n = currentQuestion ? currentQuestion.options.length : 4;
    const order = Array.from({
      length: n
    }, (_, i) => i);
    for (let i = order.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [order[i], order[j]] = [order[j], order[i]];
    }
    setOptionOrder(order);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [unitIdx, quizIdx, phase, currentOrigIdx]);

  // ── Keyboard navigation ────────────────────────────────────────
  // Arrow keys move between options; Enter submits or advances;
  // A–D or 1–4 jump directly to that option slot. On lesson and
  // complete screens, Enter is the "continue" button.
  useEffect(() => {
    const onKey = e => {
      // Don't steal keys while the user is typing in a text/number field
      const tag = e.target && e.target.tagName || '';
      const isTyping = tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT';
      if (phase === 'lesson') {
        if (e.key === 'Enter' && !isTyping) {
          e.preventDefault();
          startQuiz();
        }
        return;
      }
      if (phase === 'complete') {
        if (e.key === 'Enter' && !isTyping) {
          e.preventDefault();
          handleRestart();
        }
        return;
      }

      // phase === 'quiz'
      // Backspace / PageUp navigate to the previous question in either
      // answered or unanswered state.
      if ((e.key === 'Backspace' || e.key === 'PageUp') && !isTyping) {
        if (quizIdx > 0) {
          e.preventDefault();
          handleBack();
          return;
        }
      }
      if (e.key === 'PageDown' && !isTyping && revealed) {
        e.preventDefault();
        handleNext();
        return;
      }
      if (revealed) {
        if (e.key === 'Enter' && !isTyping) {
          e.preventDefault();
          handleNext();
        }
        return;
      }

      // Not revealed → arrows navigate, Enter submits, A-D/1-4 jump
      const n = optionOrder.length;
      if (n === 0) return;
      const currentDisplayIdx = selected === null ? -1 : optionOrder.indexOf(selected);
      if (e.key === 'ArrowDown' || e.key === 'ArrowRight') {
        e.preventDefault();
        const nextIdx = ((currentDisplayIdx < 0 ? -1 : currentDisplayIdx) + 1 + n) % n;
        setSelected(optionOrder[nextIdx]);
      } else if (e.key === 'ArrowUp' || e.key === 'ArrowLeft') {
        e.preventDefault();
        const prevIdx = ((currentDisplayIdx < 0 ? 0 : currentDisplayIdx) - 1 + n) % n;
        setSelected(optionOrder[prevIdx]);
      } else if (e.key === 'Enter') {
        if (selected !== null && !isTyping) {
          e.preventDefault();
          handleSubmit();
        }
      } else if (!isTyping) {
        // A/B/C/D or 1/2/3/4 → select that slot directly
        const k = e.key.toLowerCase();
        const letterIdx = {
          a: 0,
          b: 1,
          c: 2,
          d: 3
        }[k];
        const numIdx = {
          '1': 0,
          '2': 1,
          '3': 2,
          '4': 3
        }[k];
        const targetDisplay = letterIdx !== undefined ? letterIdx : numIdx !== undefined ? numIdx : -1;
        if (targetDisplay >= 0 && targetDisplay < n) {
          e.preventDefault();
          setSelected(optionOrder[targetDisplay]);
        }
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [phase, revealed, selected, optionOrder, quizIdx, unitIdx, perQuestion, activeIndices]);

  // ── Helpers ─────────────────────────────────────────────────────

  const handleTimeout = async () => {
    if (typeof revealed !== 'undefined' && revealed) return;
    if (typeof finished !== 'undefined' && finished) return;
    if (typeof phase !== 'undefined' && phase === 'finished') return;
    try {
      if (typeof setIsCorrect !== 'undefined') setIsCorrect(false);
    } catch (_) {}
    try {
      if (typeof setRevealed !== 'undefined') setRevealed(true);
    } catch (_) {}
    try {
      if (typeof setFeedback !== 'undefined') setFeedback("⏰ Time's up!");
    } catch (_) {}
    const timeTaken = timer.stop ? timer.stop() : 0;
    const qPrompt = question ? question.prompt || question.question || (question.n1 !== undefined ? `${question.n1} ${question.op || '+'} ${question.n2}` : 'Question') : 'Question';
    try {
      const r = await fetch(`${API}/riya-api/check`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': authGetToken() ? `Bearer ${authGetToken()}` : ''
        },
        body: JSON.stringify({
          ...(typeof question !== 'undefined' ? question : {}),
          userAnswer: '',
          answer: '',
          sessionGoal
        })
      });
      const d = await r.json();
      const corrAns = d.display || d.correctAnswer || d.answer || '—';
      if (typeof setResults === 'function') {
        setResults(prev => [...prev, {
          prompt: qPrompt,
          question: qPrompt,
          userAnswer: '(timeout)',
          correctAnswer: corrAns,
          correct: false,
          time: timeTaken
        }]);
      }
      if (sessionGoal === 'perfect') {
        try {
          if (typeof setFinished === 'function') setFinished(true);
          if (typeof setPhase === 'function') setPhase('finished');
          timer.reset();
        } catch (_) {}
      }
    } catch (e) {
      console.error('handleTimeout error:', e);
      if (typeof setResults === 'function') {
        setResults(prev => [...prev, {
          prompt: qPrompt,
          question: qPrompt,
          userAnswer: '(timeout)',
          correctAnswer: '—',
          correct: false,
          time: timeTaken
        }]);
      }
    }
  };
  const startQuiz = () => {
    setPhase('quiz');
    setQuizIdx(0);
    setPerQuestion([]);
    setSelected(null);
    setRevealed(false);
    setShowSolve(false);
  };
  const handleSubmit = () => {
    if (selected === null || revealed) return;
    const q = currentQuestion;
    if (!q) return;
    const ok = selected === q.correctIndex;
    setRevealed(true);
    // Record this question's outcome
    setPerQuestion(prev => {
      const next = [...prev];
      next[quizIdx] = {
        selected,
        revealed: true
      };
      return next;
    });
    setTotalAttempted(n => n + 1);
    if (ok) setTotalCorrect(n => n + 1);
  };

  // Go to a given position in activeIndices. Snapshots current state into
  // perQuestion and loads whatever the student had for the destination
  // (so Back lets them review the answer they submitted).
  const goTo = newIdx => {
    if (newIdx < 0 || newIdx >= activeIndices.length) return;
    const snapshot = {
      selected,
      revealed
    };
    const nextPQ = [...perQuestion];
    nextPQ[quizIdx] = snapshot;
    setPerQuestion(nextPQ);
    const dest = nextPQ[newIdx];
    if (dest) {
      setSelected(dest.selected);
      setRevealed(dest.revealed);
    } else {
      setSelected(null);
      setRevealed(false);
    }
    setShowSolve(false);
    setQuizIdx(newIdx);
  };
  const handleBack = () => {
    if (quizIdx === 0) return;
    goTo(quizIdx - 1);
  };
  const handleNext = () => {
    const last = quizIdx + 1 >= activeIndices.length;
    if (!last) {
      goTo(quizIdx + 1);
      return;
    }
    // Last question of the current round. Snapshot the last answer first.
    const finalPQ = [...perQuestion];
    finalPQ[quizIdx] = {
      selected,
      revealed
    };

    // Count correct in this round
    const correctThisRound = finalPQ.reduce((n, s, i) => {
      if (!s || !s.revealed) return n;
      const origIdx = activeIndices[i];
      const q = unit.questions[origIdx];
      return s.selected === q.correctIndex ? n + 1 : n;
    }, 0);

    // Pass rule:
    //   First pass through the unit (reviewMode=false): ≥ passThreshold.
    //   Retry (reviewMode=true): must get all re-asked questions correct.
    const passed = reviewMode ? correctThisRound === activeIndices.length : correctThisRound >= passThreshold;
    setUnitResults(r => [...r, {
      title: unit.title,
      correct: correctThisRound,
      total: activeIndices.length,
      passed,
      reviewed: reviewMode
    }]);
    if (passed) {
      if (unitIdx + 1 >= totalUnits) {
        setPhase('complete');
      } else {
        const nextUnitIdx = unitIdx + 1;
        setUnitIdx(nextUnitIdx);
        setPhase('lesson');
        setReviewMode(false);
        setActiveIndices(RIYA_UNITS[nextUnitIdx].questions.map((_, i) => i));
      }
    } else {
      // Adaptive retry: re-ask only the wrong ones
      const wrongIdxsInRound = [];
      finalPQ.forEach((s, i) => {
        if (!s || !s.revealed) {
          wrongIdxsInRound.push(i);
          return;
        }
        const q = unit.questions[activeIndices[i]];
        if (s.selected !== q.correctIndex) wrongIdxsInRound.push(i);
      });
      const newActive = wrongIdxsInRound.length > 0 ? wrongIdxsInRound.map(i => activeIndices[i]) : activeIndices; // safety net — should not normally happen
      setActiveIndices(newActive);
      setPhase('lesson');
      setReviewMode(true);
    }
    setQuizIdx(0);
    setPerQuestion([]);
    setSelected(null);
    setRevealed(false);
    setShowSolve(false);
  };
  const handleRestart = () => {
    setUnitIdx(0);
    setPhase('lesson');
    setQuizIdx(0);
    setPerQuestion([]);
    setSelected(null);
    setRevealed(false);
    setShowSolve(false);
    setTotalCorrect(0);
    setTotalAttempted(0);
    setReviewMode(false);
    setUnitResults([]);
    setActiveIndices(RIYA_UNITS[0].questions.map((_, i) => i));
  };

  // ── Rendering ───────────────────────────────────────────────────
  // Progress bar
  const progressPct = Math.round(100 * unitIdx / totalUnits);
  const renderProgress = () => <div style={{
    margin: '8px auto 14px',
    maxWidth: 480
  }}>
      <div style={{
      fontSize: '0.82rem',
      color: 'var(--clr-text-soft)',
      marginBottom: 4,
      textAlign: 'center'
    }}>
        Unit {Math.min(unitIdx + 1, totalUnits)} of {totalUnits} · {unit ? unit.title : ''}
      </div>
      <div style={{
      height: 8,
      background: 'var(--clr-bg-soft, rgba(128,128,128,0.2))',
      borderRadius: 999,
      overflow: 'hidden'
    }}>
        <div style={{
        width: `${progressPct}%`,
        height: '100%',
        background: 'var(--clr-accent)',
        transition: 'width 300ms ease'
      }} />
      </div>
    </div>;

  // Complete screen
  if (phase === 'complete') {
    const pct = totalAttempted ? Math.round(100 * totalCorrect / totalAttempted) : 0;
    return <QuizLayout title="Riya — course complete" subtitle={`You cleared all ${totalUnits} units. Overall: ${totalCorrect} / ${totalAttempted} (${pct}%)`} onBack={onBack}>
        <div style={{
        textAlign: 'center',
        marginTop: 16,
        marginBottom: 16
      }}>
          <button className="submit-btn" onClick={handleRestart}>Start Over</button>
        </div>
        <div style={{
        maxWidth: 520,
        margin: '0 auto'
      }}>
          {unitResults.map((r, i) => <div key={i} style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          padding: '8px 12px',
          borderRadius: 8,
          marginBottom: 6,
          background: 'var(--clr-bg-soft, rgba(128,128,128,0.08))'
        }}>
              <span>{i + 1}. {r.title}</span>
              <span style={{
            color: r.correct === r.total ? 'var(--clr-correct)' : 'var(--clr-text-soft)'
          }}>
                {r.correct}/{r.total}{r.reviewed ? ' · reviewed' : ''}
              </span>
            </div>)}
        </div>
      </QuizLayout>;
  }

  // Lesson phase
  if (phase === 'lesson') {
    return <QuizLayout title={`Lesson ${unitIdx + 1}: ${unit.title}`} subtitle={reviewMode ? 'Let us review this together, then try again.' : 'Read the short lesson, then try five practice questions.'} onBack={onBack}>
        {renderProgress()}
        <div style={{
        maxWidth: 560,
        margin: '0 auto'
      }}>
          <div style={{
          padding: '14px 18px',
          borderRadius: 10,
          marginBottom: 14,
          background: 'var(--clr-bg-soft, rgba(128,128,128,0.08))',
          borderLeft: '3px solid var(--clr-accent)',
          fontSize: '1rem',
          lineHeight: 1.5
        }}>
            {unit.intro}
          </div>
          {unit.examples.map((ex, i) => <div key={i} style={{
          padding: '12px 16px',
          borderRadius: 10,
          marginBottom: 12,
          border: '1px solid var(--clr-accent)'
        }}>
              <div style={{
            fontSize: '0.8rem',
            color: 'var(--clr-text-soft)',
            textTransform: 'uppercase',
            letterSpacing: 0.5
          }}>
                Example {i + 1}
              </div>
              <div style={{
            fontSize: '1.05rem',
            fontWeight: 600,
            marginTop: 4
          }}>{ex.problem}</div>
              <div style={{
            fontSize: '0.95rem',
            color: 'var(--clr-correct)',
            marginTop: 4
          }}>
                Answer: {ex.answer}
              </div>
              <ol style={{
            margin: '8px 0 0 18px',
            padding: 0,
            lineHeight: 1.5
          }}>
                {ex.steps.map((s, j) => <li key={j}>{s}</li>)}
              </ol>
            </div>)}
          <div style={{
          textAlign: 'center',
          marginTop: 16
        }}>
            <button className="submit-btn" onClick={startQuiz}>
              {reviewMode ? 'Try the practice again' : 'Start practice'}
            </button>
          </div>
        </div>
      </QuizLayout>;
  }

  // Quiz phase
  const q = currentQuestion;
  const isCorrect = q && selected === q.correctIndex;
  // Count answered + correct so far in this round, based on perQuestion
  // plus whatever the student has just selected for the current slot.
  const snapshotForCount = perQuestion.map((s, i) => i === quizIdx ? {
    selected,
    revealed
  } : s);
  const roundAnswered = snapshotForCount.filter(s => s && s.revealed).length;
  const roundCorrect = snapshotForCount.reduce((n, s, i) => {
    if (!s || !s.revealed) return n;
    const qq = unit.questions[activeIndices[i]];
    return qq && s.selected === qq.correctIndex ? n + 1 : n;
  }, 0);
  const roundTotal = activeIndices.length;
  // Pass rule for the subtitle text
  const needText = reviewMode ? `need all ${roundTotal} correct to pass` : `need ${Math.min(passThreshold, roundTotal)} correct to advance`;
  return <QuizLayout title={`Practice: ${unit.title}`} subtitle={`Question ${quizIdx + 1} of ${roundTotal} · ${needText}${reviewMode ? ' · retry round' : ''}`} onBack={onBack}>
      {renderProgress()}
      <div className="progress-pill center" style={{
      marginBottom: 12
    }}>
        Correct in this round: {roundCorrect} / {roundAnswered}
      </div>
      <div style={{
      fontSize: '0.78rem',
      color: 'var(--clr-text-soft)',
      textAlign: 'center',
      marginBottom: 6,
      opacity: 0.7
    }}>
        keyboard: ↑ ↓ to move · A–D or 1–4 to pick · Backspace back · Enter to {revealed ? 'continue' : 'submit'}
      </div>
      <div className="question-box" style={{
      whiteSpace: 'pre-wrap',
      textAlign: 'center',
      marginBottom: 16
    }}>
        <GlossaryText text={q.prompt || ''} />
      </div>
      <div className="options-list">
        {optionOrder.map((origIdx, displayIdx) => {
        const opt = q.options[origIdx];
        const letter = String.fromCharCode(65 + displayIdx);
        const isSel = selected === origIdx;
        const isRight = revealed && origIdx === q.correctIndex;
        const isWrongPick = revealed && isSel && origIdx !== q.correctIndex;
        let extra = '';
        if (isRight) extra = 'selected';else if (isSel && !revealed) extra = 'selected';
        return <label key={origIdx} className={`option-card ${extra}`} style={{
          borderColor: isRight ? 'var(--clr-correct)' : isWrongPick ? 'var(--clr-wrong)' : undefined,
          background: isRight ? 'var(--clr-correct-bg)' : isWrongPick ? 'var(--clr-wrong-bg)' : undefined,
          opacity: revealed && !isRight && !isWrongPick ? 0.7 : 1
        }}>
              <input type="radio" name="riya" checked={isSel} onChange={() => !revealed && setSelected(origIdx)} disabled={revealed} />
              <span><strong>{letter})</strong> {opt}</span>
            </label>;
      })}
      </div>
      {revealed && !showSolve && (() => {
      // Find which display position currently holds the correct option
      const correctDisplayIdx = optionOrder.indexOf(q.correctIndex);
      const correctLetter = String.fromCharCode(65 + (correctDisplayIdx >= 0 ? correctDisplayIdx : 0));
      return <div className={`feedback ${isCorrect ? 'correct' : 'wrong'}`} style={{
        marginTop: 14,
        textAlign: 'center'
      }}>
            {isCorrect ? 'Correct!' : `Correct answer: ${correctLetter}) ${q.options[q.correctIndex]}`}
          </div>;
    })()}
      {showSolve && renderFeedback(q.explanation, false)}
      <div className="button-row" style={{
      marginTop: 16
    }}>
        <button onClick={handleBack} disabled={quizIdx === 0} style={{
        background: 'transparent',
        border: '1px solid var(--clr-text-soft)',
        color: 'var(--clr-text-soft)',
        opacity: quizIdx === 0 ? 0.4 : 1,
        cursor: quizIdx === 0 ? 'not-allowed' : 'pointer'
      }}>
          ← Back
        </button>
        {!revealed ? <button onClick={handleSubmit} disabled={selected === null}>Submit</button> : <button onClick={handleNext}>{quizIdx + 1 >= roundTotal ? 'Finish round' : 'Next →'}</button>}
        <button onClick={() => setShowSolve(s => !s)} style={{
        background: 'transparent',
        border: '1px solid var(--clr-accent)',
        color: 'var(--clr-accent)'
      }}>
          {showSolve ? 'Hide Explanation' : 'Explanation'}
        </button>
      </div>
    </QuizLayout>;
}

/**
 * TatsavitLineApp — interactive line-fitting exercise at /tatsavit.
 * Two random integer points (p1, p2) appear on an XY plane. The student
 * types values for slope m and intercept C; the line y = m·x + C redraws
 * live. When the line passes through both points (within a small epsilon)
 * a "Correct" banner appears. "Next" generates a fresh pair of points.
 *
 * Point generation strategy:
 *   - Pick a target slope m ∈ {-3,...,3} (integer) and intercept
 *     C ∈ {-4,...,4}; pick two distinct x-values in [-6, 6]; compute
 *     y = mx + C for each. If either y is out of the plot window [-7, 7],
 *     retry. This guarantees a tidy integer answer and visible points.
 */
function TatsavitLineApp({
  onBack
}) {
  // `round` is just a counter that forces regeneration on Next
  const [round, setRound] = useState(0);
  // Point coordinates are stored as strings so the inputs stay editable
  // (allowing intermediate states like "", "-", "1.").
  const [p1xS, setP1xS] = useState('0');
  const [p1yS, setP1yS] = useState('0');
  const [p2xS, setP2xS] = useState('1');
  const [p2yS, setP2yS] = useState('0');
  const [mInput, setMInput] = useState('');
  const [cInput, setCInput] = useState('');
  const [showAnswer, setShowAnswer] = useState(false);
  const [solvedCount, setSolvedCount] = useState(0);
  const [justSolved, setJustSolved] = useState(false);
  // Visible domain on each axis (±zoom units). Smaller = zoomed in.
  const [zoom, setZoom] = useState(10);
  const [sessionGoal, setSessionGoal] = useState(isGoalMode ? 'speed' : 'standard');
  useEffect(() => {
    if (!isGoalMode) {
      setSessionGoal('standard');
    }
  }, [isGoalMode]);
  const svgRef = useRef(null);

  // Regenerate random points when `round` changes
  useEffect(() => {
    const mChoices = [-3, -2, -1, 0, 1, 2, 3];
    const cChoices = [-4, -3, -2, -1, 0, 1, 2, 3, 4];
    let chosen = null;
    for (let attempt = 0; attempt < 40 && !chosen; attempt++) {
      const m = mChoices[Math.floor(Math.random() * mChoices.length)];
      const c = cChoices[Math.floor(Math.random() * cChoices.length)];
      // Pick two distinct x-values in [-6, 6]
      const x1 = Math.floor(Math.random() * 13) - 6;
      let x2 = Math.floor(Math.random() * 13) - 6;
      while (x2 === x1) x2 = Math.floor(Math.random() * 13) - 6;
      const y1 = m * x1 + c;
      const y2 = m * x2 + c;
      if (Math.abs(y1) <= 7 && Math.abs(y2) <= 7) {
        chosen = {
          m,
          c,
          p1: {
            x: x1,
            y: y1
          },
          p2: {
            x: x2,
            y: y2
          }
        };
      }
    }
    if (!chosen) {
      // Ultra-safe fallback
      chosen = {
        m: 1,
        c: 0,
        p1: {
          x: -2,
          y: -2
        },
        p2: {
          x: 3,
          y: 3
        }
      };
    }
    setP1xS(String(chosen.p1.x));
    setP1yS(String(chosen.p1.y));
    setP2xS(String(chosen.p2.x));
    setP2yS(String(chosen.p2.y));
    setMInput('');
    setCInput('');
    setShowAnswer(false);
    setJustSolved(false);
  }, [round]);

  // Parse a numeric input string; returns NaN for incomplete inputs
  // ("", "-", ".", "-.") so typing does not break the plot.
  const parseNum = s => {
    if (s === '' || s === '-' || s === '.' || s === '-.') return NaN;
    const n = parseFloat(s);
    return Number.isFinite(n) ? n : NaN;
  };
  const p1x = parseNum(p1xS);
  const p1y = parseNum(p1yS);
  const p2x = parseNum(p2xS);
  const p2y = parseNum(p2yS);
  const hasValidPoints = [p1x, p1y, p2x, p2y].every(n => !Number.isNaN(n));
  const isVertical = hasValidPoints && Math.abs(p2x - p1x) < 1e-9;
  const p1 = {
    x: hasValidPoints ? p1x : 0,
    y: hasValidPoints ? p1y : 0
  };
  const p2 = {
    x: hasValidPoints ? p2x : 0,
    y: hasValidPoints ? p2y : 0
  };

  // Target line (y = targetM·x + targetC) computed from the *current*
  // (possibly edited) points. If the two points share an x-coordinate,
  // the line is vertical and cannot be represented as y = mx + C.
  let targetM = 0;
  let targetC = 0;
  let targetValid = false;
  if (hasValidPoints && !isVertical) {
    targetM = (p2y - p1y) / (p2x - p1x);
    targetC = p1y - targetM * p1x;
    targetValid = true;
  }

  // Derived state: parsed m/C inputs and correctness
  const mVal = parseNum(mInput);
  const cVal = parseNum(cInput);
  const hasValidInputs = !Number.isNaN(mVal) && !Number.isNaN(cVal);
  // Use a tolerance that scales with the problem so integer answers feel
  // forgiving but decimal answers still require reasonable precision.
  const EPS = 1e-3;
  const isCorrect = targetValid && hasValidInputs && Math.abs(mVal - targetM) < EPS && Math.abs(cVal - targetC) < EPS;

  // Flip `justSolved` once, when the student first hits the right answer
  // for the current round. This lets us briefly show a success banner
  // without blocking typing corrections afterwards.
  useEffect(() => {
    if (isCorrect && !justSolved) {
      setJustSolved(true);
      setSolvedCount(n => n + 1);
    }
  }, [isCorrect, justSolved]);

  // If the student edits the points while a success banner is showing,
  // clear it so correctness is re-evaluated against the new target.
  useEffect(() => {
    if (justSolved) setJustSolved(false);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [p1xS, p1yS, p2xS, p2yS]);

  // ── Plot geometry ───────────────────────────────────────────────
  const PLOT = 440; // SVG viewBox size (square)
  const DOMAIN = zoom; // ±zoom units on each axis
  const scale = PLOT / (2 * DOMAIN); // px per unit
  const toPx = (px, py) => ({
    x: PLOT / 2 + px * scale,
    y: PLOT / 2 - py * scale // SVG y grows downward; flip
  });

  // Endpoints of the user's line at x = ±DOMAIN (clipped by SVG bounds)
  const userStart = hasValidInputs ? toPx(-DOMAIN, mVal * -DOMAIN + cVal) : null;
  const userEnd = hasValidInputs ? toPx(DOMAIN, mVal * DOMAIN + cVal) : null;
  const answerStart = toPx(-DOMAIN, targetM * -DOMAIN + targetC);
  const answerEnd = toPx(DOMAIN, targetM * DOMAIN + targetC);

  // ── Rendering helpers ───────────────────────────────────────────
  // Tick and label spacing adapt to zoom so the grid never becomes a mess.
  //   very zoomed in (DOMAIN ≤ 3): half-unit ticks, labels every 1
  //   typical (DOMAIN 4–12):       1-unit ticks, labels every 2
  //   zoomed out (DOMAIN 13–25):   1-unit ticks, labels every 4
  //   far out (DOMAIN > 25):       2-unit ticks, labels every 10
  const tickStep = DOMAIN <= 3 ? 0.5 : DOMAIN <= 25 ? 1 : 2;
  const labelStep = DOMAIN <= 3 ? 1 : DOMAIN <= 12 ? 2 : DOMAIN <= 25 ? 4 : 10;
  const gridTicks = [];
  // Use integer arithmetic to avoid floating-point drift on half-unit ticks
  const inv = 1 / tickStep;
  const lo = -Math.round(DOMAIN * inv);
  const hi = Math.round(DOMAIN * inv);
  for (let k = lo; k <= hi; k++) gridTicks.push(k * tickStep);

  // Zoom controls
  const ZOOM_MIN = 2;
  const ZOOM_MAX = 40;
  const zoomIn = () => setZoom(z => Math.max(ZOOM_MIN, Math.round((z - 2) * 10) / 10));
  const zoomOut = () => setZoom(z => Math.min(ZOOM_MAX, Math.round((z + 2) * 10) / 10));
  const zoomReset = () => setZoom(10);
  const zoomFit = () => {
    // Fit both target points snugly with a small margin
    const maxAbs = Math.max(Math.abs(p1.x), Math.abs(p1.y), Math.abs(p2.x), Math.abs(p2.y));
    const z = Math.max(ZOOM_MIN, Math.min(ZOOM_MAX, Math.ceil(maxAbs + 1)));
    setZoom(z);
  };
  // Mouse-wheel zoom inside the SVG
  const onWheel = e => {
    e.preventDefault();
    const delta = e.deltaY > 0 ? 1 : -1; // down = zoom out
    setZoom(z => {
      // Step size scales with current zoom so wheel feels consistent
      const step = Math.max(0.5, z * 0.15);
      const next = z + delta * step;
      return Math.max(ZOOM_MIN, Math.min(ZOOM_MAX, Math.round(next * 10) / 10));
    });
  };
  useEffect(() => {
    const el = svgRef.current;
    if (!el) return;
    el.addEventListener('wheel', onWheel, {
      passive: false
    });
    return () => el.removeEventListener('wheel', onWheel);
  }, []);

  // Format numbers tidily: integers as-is, decimals rounded to 4 places
  // (trailing zeros trimmed), with a minus sign.
  const fmtNum = n => {
    if (!Number.isFinite(n)) return '?';
    if (Number.isInteger(n)) return String(n);
    return String(parseFloat(n.toFixed(4)));
  };
  const formatEq = () => {
    if (!hasValidInputs) return 'y = ?·x + ?';
    const mStr = fmtNum(mVal);
    if (cVal === 0) return `y = ${mStr}·x`;
    const sign = cVal >= 0 ? '+' : '−';
    return `y = ${mStr}·x ${sign} ${fmtNum(Math.abs(cVal))}`;
  };
  const handleNext = () => setRound(r => r + 1);
  const handleReset = () => {
    setMInput('');
    setCInput('');
    setShowAnswer(false);
  };
  return <QuizLayout title="Tatsavit — Fit the Line" subtitle={`Find m and C so y = m·x + C passes through both points · solved: ${solvedCount}`} onBack={onBack}>
      <div style={{
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      gap: 14,
      maxWidth: 560,
      margin: '0 auto'
    }}>
        {/* Zoom controls — above the plot */}
        <div style={{
        display: 'flex',
        alignItems: 'center',
        gap: 8,
        flexWrap: 'wrap',
        justifyContent: 'center'
      }}>
          <button onClick={zoomIn} title="Zoom in" style={{
          padding: '4px 12px',
          background: 'transparent',
          border: '1px solid var(--clr-accent)',
          color: 'var(--clr-accent)',
          borderRadius: 6
        }}>
            +
          </button>
          <button onClick={zoomOut} title="Zoom out" style={{
          padding: '4px 12px',
          background: 'transparent',
          border: '1px solid var(--clr-accent)',
          color: 'var(--clr-accent)',
          borderRadius: 6
        }}>
            −
          </button>
          <button onClick={zoomReset} title="Reset zoom" style={{
          padding: '4px 10px',
          background: 'transparent',
          border: '1px solid var(--clr-text-soft)',
          color: 'var(--clr-text-soft)',
          borderRadius: 6,
          fontSize: '0.85rem'
        }}>
            1:1
          </button>
          <button onClick={zoomFit} title="Fit both points" style={{
          padding: '4px 10px',
          background: 'transparent',
          border: '1px solid var(--clr-text-soft)',
          color: 'var(--clr-text-soft)',
          borderRadius: 6,
          fontSize: '0.85rem'
        }}>
            Fit
          </button>
          <span style={{
          fontSize: '0.8rem',
          color: 'var(--clr-text-soft)',
          marginLeft: 6
        }}>
            view ±{zoom}
          </span>
        </div>

        {/* SVG plot */}
        <svg ref={svgRef} viewBox={`0 0 ${PLOT} ${PLOT}`} style={{
        width: 'min(92vw, 460px)',
        height: 'min(92vw, 460px)',
        background: 'var(--clr-bg-soft, rgba(128,128,128,0.06))',
        border: '1px solid var(--clr-text-soft)',
        borderRadius: 8,
        touchAction: 'none',
        overflow: 'hidden'
      }}>
          {/* Grid lines */}
          {gridTicks.map(g => {
          const {
            x: gx
          } = toPx(g, 0);
          const {
            y: gy
          } = toPx(0, g);
          const axis = g === 0;
          return <g key={`grid-${g}`}>
                <line x1={gx} y1={0} x2={gx} y2={PLOT} stroke="currentColor" strokeOpacity={axis ? 0.55 : 0.12} strokeWidth={axis ? 1.5 : 0.6} />
                <line x1={0} y1={gy} x2={PLOT} y2={gy} stroke="currentColor" strokeOpacity={axis ? 0.55 : 0.12} strokeWidth={axis ? 1.5 : 0.6} />
              </g>;
        })}
          {/* Axis tick labels (spacing adapts to zoom) */}
          {gridTicks.filter(g => {
          if (g === 0) return false;
          // Show a label when g is (close to) a multiple of labelStep
          const q = g / labelStep;
          return Math.abs(q - Math.round(q)) < 1e-9;
        }).map(g => {
          const {
            x: gx
          } = toPx(g, 0);
          const {
            y: gy
          } = toPx(0, g);
          const origin = toPx(0, 0);
          return <g key={`lbl-${g}`} style={{
            fontSize: 10,
            fill: 'currentColor',
            opacity: 0.55
          }}>
                <text x={gx} y={origin.y + 13} textAnchor="middle">{g}</text>
                <text x={origin.x - 6} y={gy + 3} textAnchor="end">{g}</text>
              </g>;
        })}
          {/* Show-answer dashed line (only when a y = mx + C line exists) */}
          {showAnswer && !isCorrect && targetValid && <line x1={answerStart.x} y1={answerStart.y} x2={answerEnd.x} y2={answerEnd.y} stroke="var(--clr-correct, #26de81)" strokeWidth={2} strokeDasharray="6 4" strokeOpacity={0.7} />}
          {/* User's line */}
          {hasValidInputs && userStart && userEnd && <line x1={userStart.x} y1={userStart.y} x2={userEnd.x} y2={userEnd.y} stroke={isCorrect ? 'var(--clr-correct, #26de81)' : 'var(--clr-accent, #4a90e2)'} strokeWidth={3} strokeOpacity={0.9} />}
          {/* Target points — only render when coordinates parse cleanly */}
          {hasValidPoints && [p1, p2].map((p, i) => {
          const {
            x,
            y
          } = toPx(p.x, p.y);
          return <g key={i}>
                <circle cx={x} cy={y} r={7} fill="var(--clr-wrong, #ff6b6b)" stroke="var(--clr-bg, #fff)" strokeWidth={2} />
                <text x={x + 10} y={y - 10} style={{
              fontSize: 12,
              fill: 'currentColor',
              fontWeight: 600
            }}>
                  ({fmtNum(p.x)}, {fmtNum(p.y)})
                </text>
              </g>;
        })}
        </svg>

        {/* Editable coordinates for the two target points */}
        <div style={{
        display: 'grid',
        gridTemplateColumns: 'auto auto auto',
        alignItems: 'center',
        gap: '8px 10px',
        fontSize: '0.95rem'
      }}>
          <span style={{
          color: 'var(--clr-text-soft)'
        }}>Point 1</span>
          <input type="number" value={p1xS} onChange={e => setP1xS(e.target.value)} step="0.1" aria-label="Point 1 x" style={{
          width: 72,
          padding: '6px 8px',
          borderRadius: 6,
          border: '1px solid var(--clr-text-soft)',
          background: 'transparent',
          color: 'inherit',
          textAlign: 'center',
          fontFamily: 'monospace'
        }} />
          <input type="number" value={p1yS} onChange={e => setP1yS(e.target.value)} step="0.1" aria-label="Point 1 y" style={{
          width: 72,
          padding: '6px 8px',
          borderRadius: 6,
          border: '1px solid var(--clr-text-soft)',
          background: 'transparent',
          color: 'inherit',
          textAlign: 'center',
          fontFamily: 'monospace'
        }} />
          <span style={{
          color: 'var(--clr-text-soft)'
        }}>Point 2</span>
          <input type="number" value={p2xS} onChange={e => setP2xS(e.target.value)} step="0.1" aria-label="Point 2 x" style={{
          width: 72,
          padding: '6px 8px',
          borderRadius: 6,
          border: '1px solid var(--clr-text-soft)',
          background: 'transparent',
          color: 'inherit',
          textAlign: 'center',
          fontFamily: 'monospace'
        }} />
          <input type="number" value={p2yS} onChange={e => setP2yS(e.target.value)} step="0.1" aria-label="Point 2 y" style={{
          width: 72,
          padding: '6px 8px',
          borderRadius: 6,
          border: '1px solid var(--clr-text-soft)',
          background: 'transparent',
          color: 'inherit',
          textAlign: 'center',
          fontFamily: 'monospace'
        }} />
        </div>

        {isVertical && <div style={{
        fontSize: '0.9rem',
        color: 'var(--clr-wrong, #ff6b6b)',
        textAlign: 'center',
        maxWidth: 360
      }}>
            Point 1 and Point 2 share the same x-coordinate — a vertical line cannot be written as y = m·x + C. Change one of the x-values to continue.
          </div>}

        {/* Inputs for m and C */}
        <div style={{
        display: 'flex',
        gap: 18,
        alignItems: 'flex-end',
        flexWrap: 'wrap',
        justifyContent: 'center'
      }}>
          <label style={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          gap: 4
        }}>
            <span style={{
            fontSize: '0.82rem',
            color: 'var(--clr-text-soft)'
          }}>slope m</span>
            <input type="number" value={mInput} onChange={e => setMInput(e.target.value)} step="0.1" placeholder="?" style={{
            width: 110,
            padding: '8px 12px',
            borderRadius: 8,
            border: '1px solid var(--clr-text-soft)',
            background: 'transparent',
            color: 'inherit',
            textAlign: 'center',
            fontSize: '1.15rem',
            fontFamily: 'monospace'
          }} />
          </label>
          <label style={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          gap: 4
        }}>
            <span style={{
            fontSize: '0.82rem',
            color: 'var(--clr-text-soft)'
          }}>intercept C</span>
            <input type="number" value={cInput} onChange={e => setCInput(e.target.value)} step="0.1" placeholder="?" style={{
            width: 110,
            padding: '8px 12px',
            borderRadius: 8,
            border: '1px solid var(--clr-text-soft)',
            background: 'transparent',
            color: 'inherit',
            textAlign: 'center',
            fontSize: '1.15rem',
            fontFamily: 'monospace'
          }} />
          </label>
        </div>

        <div style={{
        fontSize: '1.05rem',
        fontFamily: 'monospace',
        marginTop: 4,
        color: 'var(--clr-text-soft)'
      }}>
          {formatEq()}
        </div>

        {isCorrect && <div className="feedback correct" style={{
        textAlign: 'center',
        fontSize: '1.05rem',
        color: 'var(--clr-correct, #26de81)',
        fontWeight: 600,
        padding: '8px 16px',
        borderRadius: 8,
        background: 'var(--clr-correct-bg, rgba(38,222,129,0.12))'
      }}>
            ✓ The line passes through both points.
          </div>}
        {showAnswer && !isCorrect && targetValid && <div style={{
        fontSize: '0.95rem',
        color: 'var(--clr-text-soft)',
        textAlign: 'center'
      }}>
            Answer: m = {fmtNum(targetM)}, C = {fmtNum(targetC)}
          </div>}
        {showAnswer && !targetValid && <div style={{
        fontSize: '0.95rem',
        color: 'var(--clr-text-soft)',
        textAlign: 'center'
      }}>
            No y = m·x + C line exists for these points yet.
          </div>}

        <div className="button-row" style={{
        marginTop: 6
      }}>
          <button onClick={handleNext} className="submit-btn">Next →</button>
          <button onClick={handleReset} style={{
          background: 'transparent',
          border: '1px solid var(--clr-text-soft)',
          color: 'var(--clr-text-soft)'
        }}>
            Reset
          </button>
          <button onClick={() => setShowAnswer(s => !s)} style={{
          background: 'transparent',
          border: '1px solid var(--clr-accent)',
          color: 'var(--clr-accent)'
        }}>
            {showAnswer ? 'Hide answer' : 'Show answer'}
          </button>
        </div>
      </div>
    </QuizLayout>;
}

// The Vachana Literary Lab is now imported from its own directory to avoid bloating App.jsx.

/**
 * QuizLayout Component
 * Wrapper layout for quiz apps (PolyFactorApp, PrimeFactorApp, QFormulaApp, etc.)
 * Provides consistent header with back button and title section
 * All quiz content is rendered via children prop
 *
 * @param {Object} props
 * @param {string} props.title - Main heading (e.g., "Prime Factors")
 * @param {string} props.subtitle - Subtitle/description
 * @param {Function} props.onBack - Callback when back button is clicked
 * @param {React.ReactNode} props.children - Quiz content to display
 */
export function QuizLayout({
  title,
  subtitle,
  onBack,
  children,
  timer,
  sessionGoal
}) {
  // Derive display values from the timer object
  const isSpeed = timer && (timer.mode === 'speed' || sessionGoal === 'speed');
  const isPerfect = sessionGoal === 'perfect';

  // For speed mode: show remaining seconds with urgency colouring
  const timerDisplay = (() => {
    if (!timer) return null;
    if (isPerfect) return null; // hide timer entirely for perfect solve
    if (isSpeed) {
      const left = timer.remaining ?? 0;
      const urgent = left <= 3;
      const warn = left <= 5 && !urgent;
      const color = urgent ? '#f44336' : warn ? '#ff9800' : '#4caf50';
      return <div className="timer-pill" style={{
        background: urgent ? 'rgba(244,67,54,0.15)' : warn ? 'rgba(255,152,0,0.15)' : undefined,
        borderColor: color,
        color,
        fontWeight: 700,
        fontSize: '1rem',
        minWidth: 56,
        textAlign: 'center',
        transition: 'color 0.3s, background 0.3s',
        animation: urgent ? 'timerPulse 0.5s ease-in-out infinite alternate' : 'none'
      }}>
          ⚡ {left}s
        </div>;
    }
    // Standard / revision — count-up
    return <div className="timer-pill">{timer.elapsed}s</div>;
  })();

  // Goal mode badge
  const goalBadge = (() => {
    if (!sessionGoal || sessionGoal === 'standard') return null;
    const cfg = {
      speed: {
        label: '⚡ Speed Run',
        bg: 'rgba(255,179,0,0.18)',
        border: '#ffb300',
        color: '#ffb300'
      },
      perfect: {
        label: '🎯 Perfect Solve',
        bg: 'rgba(244,67,54,0.18)',
        border: '#f44336',
        color: '#f44336'
      },
      revision: {
        label: '🔄 Revision',
        bg: 'rgba(33,150,243,0.18)',
        border: '#2196f3',
        color: '#2196f3'
      }
    }[sessionGoal];
    if (!cfg) return null;
    return <div style={{
      display: 'inline-flex',
      alignItems: 'center',
      gap: 4,
      padding: '2px 10px',
      borderRadius: 20,
      fontSize: '0.78rem',
      fontWeight: 600,
      background: cfg.bg,
      border: `1.5px solid ${cfg.border}`,
      color: cfg.color
    }}>
        {cfg.label}
      </div>;
  })();

  // Dynamically intercept children if finished and goal mode is active
  const sessionGoalActive = sessionGoal && sessionGoal !== 'standard';
  const processedChildren = React.Children.map(children, child => {
    if (sessionGoalActive) {
      return enhanceFinishedScreen(child, sessionGoal);
    }
    return child;
  });
  return <>
      <div className="header-row">
        <button className="back-button" onClick={onBack}>← Home</button>
        <div style={{
        display: 'flex',
        alignItems: 'center',
        gap: 8
      }}>
          {goalBadge}
          {timerDisplay}
        </div>
      </div>
      <h1 style={{
      fontSize: 'clamp(1.8rem, 3.8vw, 2.4rem)'
    }}>{title}</h1>
      {subtitle && <p className="subtitle">{subtitle}</p>}
      {processedChildren}
      <QuizLayoutExtension children={children} />
    </>;
}

// ─── Learning Journey Core Components ───────────────────────────────────────

const journeyFetch = async (path, options = {}) => {
  const token = authGetToken();
  const headers = {
    'Content-Type': 'application/json',
    ...options.headers
  };
  if (token) {
    headers['Authorization'] = `Bearer ${token}`;
  }
  const res = await fetch(`${API}${path}`, {
    ...options,
    headers
  });
  if (!res.ok) {
    const err = await res.json().catch(() => ({
      error: 'Request failed'
    }));
    throw new Error(err.error || `Request failed (HTTP ${res.status})`);
  }
  return res.json();
};
function LearningJourneyHome({
  onSelectTopic,
  onBack
}) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const loadProgress = async () => {
    try {
      setLoading(true);
      const res = await journeyFetch('/api/learning-journey/progress');
      setData(res);
      setError('');
    } catch (err) {
      setError(err.message || 'Failed to load progress');
    } finally {
      setLoading(false);
    }
  };
  useEffect(() => {
    loadProgress();
  }, []);
  if (loading) return <div style={{
    textAlign: 'center',
    padding: '40px'
  }}><p>Loading your journey...</p></div>;
  if (error) return <div style={{
    textAlign: 'center',
    padding: '40px',
    color: 'red'
  }}><p>{error}</p><button onClick={loadProgress} className="submit-btn" style={{
      width: 'auto'
    }}>Retry</button></div>;
  if (!data) return null;
  return <div style={{
    padding: '16px'
  }}>
      <div className="header-row" style={{
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      marginBottom: '24px'
    }}>
        <button className="back-button" onClick={onBack}>← Main Menu</button>
        <span style={{
        fontSize: '1.25rem',
        fontWeight: 'bold',
        color: 'var(--clr-accent)'
      }}>⭐ Learning Journey</span>
      </div>

      <div style={{
      background: 'var(--clr-hover-strong, rgba(255,255,255,0.03))',
      padding: '20px',
      borderRadius: '12px',
      border: '1px solid var(--clr-border)',
      marginBottom: '24px'
    }}>
        <h3 style={{
        marginTop: 0,
        marginBottom: '8px'
      }}>Overall Progress</h3>
        <div style={{
        display: 'flex',
        alignItems: 'center',
        gap: '16px'
      }}>
          <div style={{
          flex: 1,
          height: '12px',
          background: 'var(--clr-border, #444)',
          borderRadius: '6px',
          overflow: 'hidden'
        }}>
            <div style={{
            width: `${data.overallProgressPercent}%`,
            height: '100%',
            background: 'linear-gradient(90deg, #ff7e5f, #feb47b)',
            borderRadius: '6px',
            transition: 'width 0.5s ease-in-out'
          }} />
          </div>
          <span style={{
          fontWeight: 'bold',
          fontSize: '1.1rem'
        }}>{data.overallProgressPercent}% Completed</span>
        </div>
        <p style={{
        margin: '8px 0 0 0',
        fontSize: '0.85rem',
        color: 'var(--clr-text-soft)'
      }}>
          Completed {data.completedConcepts.length} concepts across {data.completedTopics.length} topics.
        </p>
      </div>

      <div style={{
      display: 'grid',
      gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))',
      gap: '20px'
    }}>
        {data.topics.map((t, idx) => {
        if (!t) return null;
        const completedCount = t.concepts.filter(c => c.state === 'completed').length;
        const totalConcepts = t.concepts.length;
        return <div key={t.topicId} style={{
          position: 'relative',
          background: 'var(--clr-surface, #1c1c1f)',
          border: t.completed ? '1.5px solid var(--clr-correct, #26de81)' : t.unlocked ? '1.5px solid var(--clr-accent, #feb47b)' : '1px solid var(--clr-border, #444)',
          borderRadius: '12px',
          padding: '20px',
          opacity: t.unlocked ? 1 : 0.5,
          cursor: t.unlocked ? 'pointer' : 'not-allowed',
          boxShadow: '0 4px 12px rgba(0,0,0,0.15)',
          transition: 'transform 0.2s, box-shadow 0.2s'
        }} onClick={() => {
          if (t.unlocked) onSelectTopic(t.topicId);
        }} onMouseEnter={e => {
          if (t.unlocked) {
            e.currentTarget.style.transform = 'translateY(-3px)';
            e.currentTarget.style.boxShadow = '0 6px 16px rgba(0,0,0,0.25)';
          }
        }} onMouseLeave={e => {
          e.currentTarget.style.transform = 'none';
          e.currentTarget.style.boxShadow = '0 4px 12px rgba(0,0,0,0.15)';
        }}>
              {!t.unlocked && <div style={{
            position: 'absolute',
            top: '16px',
            right: '16px',
            fontSize: '1.2rem'
          }}>🔒</div>}
              {t.completed && <div style={{
            position: 'absolute',
            top: '16px',
            right: '16px',
            color: 'var(--clr-correct, #26de81)',
            fontSize: '1.25rem',
            fontWeight: 'bold'
          }}>✓</div>}
              <span style={{
            fontSize: '0.8rem',
            color: 'var(--clr-accent)',
            textTransform: 'uppercase',
            letterSpacing: '1px',
            fontWeight: 'bold'
          }}>
                Topic {idx + 1}
              </span>
              <h3 style={{
            marginTop: '4px',
            marginBottom: '8px'
          }}>{t.topicId.split('_').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ')}</h3>
              
              <div style={{
            display: 'flex',
            justifyContent: 'space-between',
            fontSize: '0.85rem',
            color: 'var(--clr-text-soft)',
            marginBottom: '12px'
          }}>
                <span>Concepts</span>
                <span>{completedCount} / {totalConcepts}</span>
              </div>

              {t.unlocked && <div style={{
            marginTop: '16px',
            fontSize: '0.85rem'
          }}>
                  {t.completed ? <span style={{
              color: 'var(--clr-correct, #26de81)',
              fontWeight: 'bold'
            }}>Checkpoint Cleared ({t.latestScore}%)</span> : t.checkpointEligible ? <span style={{
              color: 'orange',
              fontWeight: 'bold'
            }}>Checkpoint Ready</span> : <span style={{
              color: 'var(--clr-text-soft)'
            }}>Progressing ({Math.round(completedCount / totalConcepts * 100)}%)</span>}
                </div>}
            </div>;
      })}
      </div>
    </div>;
}
function LearningJourneyTopicView({
  topicId,
  onPlayConcept,
  onStartCheckpoint,
  onBack
}) {
  const [progression, setProgression] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const loadProgression = async () => {
    try {
      setLoading(true);
      const res = await journeyFetch('/api/learning-journey/progress');
      const topicProg = res.topics.find(t => t && t.topicId === topicId);
      if (!topicProg) throw new Error('Topic progression not found');
      setProgression(topicProg);
      setError('');
    } catch (err) {
      setError(err.message || 'Failed to load progression');
    } finally {
      setLoading(false);
    }
  };
  useEffect(() => {
    loadProgression();
  }, [topicId]);
  if (loading) return <div style={{
    textAlign: 'center',
    padding: '40px'
  }}><p>Loading topic concepts...</p></div>;
  if (error) return <div style={{
    textAlign: 'center',
    padding: '40px',
    color: 'red'
  }}><p>{error}</p><button onClick={loadProgression} className="submit-btn" style={{
      width: 'auto'
    }}>Retry</button></div>;
  if (!progression) return null;
  const displayName = topicId.split('_').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
  return <div style={{
    padding: '16px'
  }}>
      <div className="header-row" style={{
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      marginBottom: '24px'
    }}>
        <button className="back-button" onClick={onBack}>← Back to Journey</button>
        <span style={{
        fontWeight: 'bold',
        color: 'var(--clr-accent)'
      }}>Topic Path</span>
      </div>

      <div style={{
      textAlign: 'center',
      marginBottom: '32px'
    }}>
        <h2 style={{
        margin: 0
      }}>{displayName}</h2>
        <p className="subtitle">Complete each concept sequentially to unlock the Checkpoint gate.</p>
      </div>

      {/* Timeline Layout */}
      <div style={{
      display: 'flex',
      flexDirection: 'column',
      gap: '20px',
      maxWidth: '500px',
      margin: '0 auto',
      position: 'relative'
    }}>
        {progression.concepts.map((concept, index) => {
        const isCompleted = concept.state === 'completed';
        const isNeedsRevision = concept.state === 'needs_revision';
        const isPlayable = concept.state === 'playable' || isNeedsRevision;
        const isLocked = concept.state === 'locked';
        return <div key={concept.key} style={{
          display: 'flex',
          gap: '16px',
          alignItems: 'center',
          position: 'relative'
        }}>
              {/* Connector line */}
              {index < progression.concepts.length - 1 && <div style={{
            position: 'absolute',
            left: '20px',
            top: '40px',
            width: '2px',
            height: 'calc(100% - 20px)',
            background: isCompleted || isNeedsRevision ? 'var(--clr-correct, #26de81)' : 'var(--clr-border, #444)',
            zIndex: 1
          }} />}
              {/* Circle Icon */}
              <div style={{
            width: '42px',
            height: '42px',
            borderRadius: '50%',
            background: isCompleted ? 'var(--clr-correct, #26de81)' : isNeedsRevision ? '#ff9f43' : isPlayable ? 'var(--clr-accent, #feb47b)' : 'var(--clr-surface, #2c2c2f)',
            border: '2px solid ' + (isPlayable || isNeedsRevision ? '#fff' : 'var(--clr-border)'),
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontWeight: 'bold',
            color: isCompleted || isNeedsRevision || isPlayable ? '#000' : 'var(--clr-text-soft)',
            zIndex: 2,
            fontSize: '1.1rem'
          }}>
                {isCompleted ? '✓' : isNeedsRevision ? '↻' : isLocked ? '🔒' : index + 1}
              </div>

              {/* Card content */}
              <div style={{
            flex: 1,
            background: isNeedsRevision ? 'rgba(255, 159, 67, 0.08)' : isPlayable ? 'var(--clr-hover-strong, rgba(255,255,255,0.06))' : 'var(--clr-surface, #1c1c1f)',
            border: isNeedsRevision ? '1.5px dashed #ff9f43' : isPlayable ? '1.5px solid var(--clr-accent)' : '1px solid var(--clr-border)',
            borderRadius: '10px',
            padding: '12px 18px',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            opacity: isLocked ? 0.6 : 1,
            cursor: isLocked ? 'not-allowed' : 'pointer',
            transition: 'background var(--transition)'
          }} onClick={() => {
            if (!isLocked) onPlayConcept(concept.key);
          }}>
                <div>
                  <h4 style={{
                margin: 0,
                fontSize: '1.05rem'
              }}>{concept.name}</h4>
                  <span style={{
                fontSize: '0.78rem',
                color: isNeedsRevision ? '#ff9f43' : 'var(--clr-text-soft)'
              }}>
                    {isNeedsRevision ? '⚠️ Revision Required' : isCompleted ? 'Completed (Click to revise)' : isPlayable ? 'Playable Now' : 'Locked'}
                  </span>
                </div>
                {!isLocked && <span style={{
              fontSize: '1.1rem',
              color: isNeedsRevision ? '#ff9f43' : isPlayable ? 'var(--clr-accent)' : 'var(--clr-text-soft)'
            }}>▶</span>}
              </div>
            </div>;
      })}

        {/* Checkpoint Gate node */}
        <div style={{
        display: 'flex',
        gap: '16px',
        alignItems: 'center',
        marginTop: '20px'
      }}>
          <div style={{
          width: '42px',
          height: '42px',
          borderRadius: '50%',
          background: progression.completed ? 'var(--clr-correct, #26de81)' : progression.checkpointEligible ? 'orange' : 'var(--clr-surface, #2c2c2f)',
          border: '2px solid var(--clr-border)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          color: progression.completed || progression.checkpointEligible ? '#000' : 'var(--clr-text-soft)',
          zIndex: 2,
          fontSize: '1.2rem',
          fontWeight: 'bold'
        }}>
            🏁
          </div>

          <div style={{
          flex: 1,
          background: 'var(--clr-surface, #1d1d20)',
          border: progression.completed ? '2px solid var(--clr-correct, #26de81)' : progression.checkpointEligible ? '2px solid orange' : '1px solid var(--clr-border)',
          borderRadius: '12px',
          padding: '20px',
          textAlign: 'center',
          boxShadow: '0 4px 14px rgba(0,0,0,0.1)'
        }}>
            <h4 style={{
            margin: '0 0 8px 0',
            fontSize: '1.1rem'
          }}>Topic Checkpoint Quiz</h4>
            <p style={{
            margin: '0 0 16px 0',
            fontSize: '0.85rem',
            color: 'var(--clr-text-soft)'
          }}>
              15 cumulative questions. Score 80%+ to clear the topic and unlock successor topics.
            </p>

            {progression.completed ? <div style={{
            color: 'var(--clr-correct, #26de81)',
            fontWeight: 'bold',
            fontSize: '1.05rem'
          }}>
                ✓ Cleared (Score: {progression.latestScore}%)
              </div> : progression.checkpointEligible ? <div>
                {progression.latestScore !== null && <div style={{
              color: 'red',
              fontSize: '0.85rem',
              fontWeight: 'bold',
              marginBottom: '8px'
            }}>
                    Failed Previous Attempt: {progression.latestScore}% (Required: 80%)
                  </div>}
                <button className="submit-btn" onClick={onStartCheckpoint} style={{
              width: 'auto',
              padding: '10px 24px',
              background: 'orange',
              borderColor: 'orange',
              color: '#000',
              fontWeight: 'bold'
            }}>
                  Start Checkpoint Quiz
                </button>
              </div> : <div style={{
            fontSize: '0.85rem',
            color: 'var(--clr-text-soft)',
            fontStyle: 'italic'
          }}>
                🔒 Locked (Complete all concepts above to unlock)
              </div>}
          </div>
        </div>
      </div>
    </div>;
}
function LearningJourneyCheckpointQuizView({
  topicId,
  onBack
}) {
  const [quiz, setQuiz] = useState(null);
  const [currentIdx, setCurrentIdx] = useState(0);
  const [answers, setAnswers] = useState({});
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');
  const celebrationRef = useRef(null);
  const loadQuiz = async () => {
    try {
      setLoading(true);
      const res = await journeyFetch(`/api/learning-journey/checkpoint/quiz?topicId=${topicId}`);
      setQuiz(res);
      setError('');
      setAnswers({});
      setResult(null);
      setCurrentIdx(0);
    } catch (err) {
      setError(err.message || 'Failed to load quiz');
    } finally {
      setLoading(false);
    }
  };
  useEffect(() => {
    loadQuiz();
  }, [topicId]);
  useEffect(() => {
    if (!result || !result.passed || !celebrationRef.current) return;
    const canvas = celebrationRef.current;
    const ctx = canvas.getContext('2d');
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
    const colors = ['#ff6b6b', '#feca57', '#48dbfb', '#ff9ff3', '#54a0ff', '#5f27cd', '#01a3a4', '#f368e0', '#ff9f43', '#00d2d3'];
    const confetti = Array.from({
      length: 150
    }, () => ({
      x: Math.random() * canvas.width,
      y: Math.random() * canvas.height - canvas.height,
      w: Math.random() * 12 + 6,
      h: Math.random() * 8 + 4,
      color: colors[Math.floor(Math.random() * colors.length)],
      vx: (Math.random() - 0.5) * 4,
      vy: Math.random() * 3 + 2,
      rot: Math.random() * 360,
      rotSpeed: (Math.random() - 0.5) * 10
    }));
    let frame;
    const animate = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      let allDone = true;
      confetti.forEach(c => {
        c.x += c.vx;
        c.y += c.vy;
        c.rot += c.rotSpeed;
        c.vy += 0.05;
        if (c.y < canvas.height + 50) allDone = false;
        ctx.save();
        ctx.translate(c.x, c.y);
        ctx.rotate(c.rot * Math.PI / 180);
        ctx.fillStyle = c.color;
        ctx.fillRect(-c.w / 2, -c.h / 2, c.w, c.h);
        ctx.restore();
      });
      if (!allDone) frame = requestAnimationFrame(animate);
    };
    animate();
    return () => {
      if (frame) cancelAnimationFrame(frame);
    };
  }, [result]);
  const handleSelectAnswer = ansVal => {
    const qId = quiz.questions[currentIdx].id;
    setAnswers(prev => ({
      ...prev,
      [qId]: ansVal
    }));
  };
  const handleSubmit = async () => {
    try {
      setSubmitting(true);
      const res = await journeyFetch('/api/learning-journey/checkpoint/verify', {
        method: 'POST',
        body: JSON.stringify({
          topicId,
          answers
        })
      });
      setResult(res);
    } catch (err) {
      alert(err.message || 'Verification failed');
    } finally {
      setSubmitting(false);
    }
  };
  if (loading) return <div style={{
    textAlign: 'center',
    padding: '40px'
  }}><p>Generating your checkpoint questions...</p></div>;
  if (error) return <div style={{
    textAlign: 'center',
    padding: '40px',
    color: 'red'
  }}><p>{error}</p><button onClick={loadQuiz} className="submit-btn" style={{
      width: 'auto'
    }}>Retry</button></div>;
  if (!quiz) return null;
  const displayName = topicId.split('_').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');

  // Show grading results screen
  if (result) {
    return <div style={{
      padding: '16px'
    }}>
        {result.passed && <canvas ref={celebrationRef} style={{
        position: 'fixed',
        top: 0,
        left: 0,
        width: '100vw',
        height: '100vh',
        pointerEvents: 'none',
        zIndex: 9999
      }} />}
        <div style={{
        textAlign: 'center',
        marginBottom: '24px'
      }}>
          <h2 style={{
          color: result.passed ? 'var(--clr-correct, #26de81)' : 'var(--clr-wrong, #eb5e55)'
        }}>
            {result.passed ? '🎉 Checkpoint Passed!' : "Oh no, it's okay"}
          </h2>
          <h1 style={{
          margin: '8px 0',
          fontSize: '3rem'
        }}>{result.scorePercent}%</h1>
          <p className="subtitle">
            Answered {result.correctCount} of {result.totalQuestions} questions correctly.
          </p>
          {!result.passed && <div style={{
          marginTop: '16px',
          padding: '12px 20px',
          borderRadius: '8px',
          background: 'var(--clr-wrong-light, rgba(235, 94, 85, 0.1))',
          border: '1px solid var(--clr-wrong, #eb5e55)',
          color: 'var(--clr-text)',
          display: 'inline-block',
          fontSize: '0.95rem',
          maxWidth: '450px',
          lineHeight: '1.5'
        }}>
              💡 <strong>Revise back old concepts and try again.</strong> You need 80% (12/15) to pass.
            </div>}
          {result.passed && <p className="subtitle" style={{
          color: 'var(--clr-correct, #26de81)',
          marginTop: '8px'
        }}>
              The next topic has been unlocked.
            </p>}
        </div>

        <div style={{
        display: 'flex',
        gap: '12px',
        justifyContent: 'center',
        marginBottom: '32px'
      }}>
          {result.passed ? <button onClick={onBack} className="submit-btn" style={{
          width: 'auto',
          padding: '10px 24px'
        }}>
              Continue Journey
            </button> : <>
              <button onClick={loadQuiz} className="submit-btn" style={{
            width: 'auto',
            padding: '10px 24px'
          }}>
                Retry Checkpoint
              </button>
              <button onClick={onBack} className="submit-btn" style={{
            width: 'auto',
            padding: '10px 24px',
            background: 'transparent',
            color: 'var(--clr-text)',
            border: '1px solid var(--clr-border)'
          }}>
                Back to Concepts
              </button>
            </>}
        </div>

        <h3 style={{
        borderBottom: '1px solid var(--clr-border)',
        paddingBottom: '8px',
        marginBottom: '16px'
      }}>Review Questions</h3>
        <div style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '16px'
      }}>
          {result.results.map((q, idx) => <div key={q.id} style={{
          background: 'var(--clr-surface, #1c1c1f)',
          border: '1px solid ' + (q.isCorrect ? 'var(--clr-correct, #26de81)' : 'red'),
          borderRadius: '8px',
          padding: '16px',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center'
        }}>
              <div>
                <span style={{
              fontSize: '0.85rem',
              color: 'var(--clr-accent)',
              fontWeight: 'bold'
            }}>Q{idx + 1}</span>
                <p style={{
              margin: '4px 0 0 0',
              fontWeight: 'bold'
            }}>{q.prompt}</p>
                <div style={{
              marginTop: '8px',
              fontSize: '0.9rem',
              display: 'flex',
              gap: '20px'
            }}>
                  <span>Your answer: <strong style={{
                  color: q.isCorrect ? 'var(--clr-correct)' : 'red'
                }}>{q.userAnswer || '(blank)'}</strong></span>
                  {!q.isCorrect && <span>Correct answer: <strong style={{
                  color: 'var(--clr-correct)'
                }}>{q.correctAnswer}</strong></span>}
                </div>
              </div>
              <div style={{
            fontSize: '1.5rem',
            color: q.isCorrect ? 'var(--clr-correct)' : 'red'
          }}>
                {q.isCorrect ? '✓' : '✗'}
              </div>
            </div>)}
        </div>
      </div>;
  }
  const currentQ = quiz.questions[currentIdx];
  const currentAnswerVal = answers[currentQ.id] || '';
  return <div style={{
    padding: '16px'
  }}>
      <div className="header-row" style={{
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      marginBottom: '24px'
    }}>
        <button className="back-button" onClick={onBack}>← Quit Checkpoint</button>
        <span style={{
        fontSize: '0.95rem',
        color: 'orange',
        fontWeight: 'bold'
      }}>🏁 {displayName} Checkpoint</span>
      </div>

      {/* Progress display */}
      <div style={{
      display: 'flex',
      justifyContent: 'center',
      gap: '6px',
      marginBottom: '20px'
    }}>
        {quiz.questions.map((_, idx) => {
        let dotColor = 'var(--clr-border, #444)';
        if (idx === currentIdx) dotColor = 'orange';else if (answers[quiz.questions[idx].id] !== undefined) dotColor = 'var(--clr-accent, #feb47b)';
        return <div key={idx} style={{
          width: '10px',
          height: '10px',
          borderRadius: '50%',
          background: dotColor,
          transition: 'background 0.2s'
        }} />;
      })}
      </div>

      <div style={{
      textAlign: 'center',
      marginBottom: '24px'
    }}>
        <span style={{
        fontSize: '0.85rem',
        color: 'var(--clr-text-soft)',
        textTransform: 'uppercase',
        fontWeight: 'bold'
      }}>
          Question {currentIdx + 1} of 15
        </span>
        <h2 style={{
        marginTop: '8px',
        minHeight: '60px'
      }}>{currentQ.prompt}</h2>
      </div>

      <div style={{
      maxWidth: '360px',
      margin: '0 auto 32px auto'
    }}>
        <input type="text" value={currentAnswerVal} onChange={e => handleSelectAnswer(e.target.value)} placeholder="Type your answer here..." autoFocus style={{
        width: '100%',
        padding: '12px 16px',
        fontSize: '1.2rem',
        textAlign: 'center',
        background: 'var(--clr-surface, #1c1c1f)',
        border: '1.5px solid var(--clr-border)',
        borderRadius: '8px',
        color: 'var(--clr-text)',
        outline: 'none',
        fontFamily: 'monospace'
      }} onKeyDown={e => {
        if (e.key === 'Enter') {
          if (currentIdx < 14) setCurrentIdx(currentIdx + 1);else handleSubmit();
        }
      }} />
      </div>

      <div style={{
      display: 'flex',
      justifyContent: 'space-between',
      maxWidth: '360px',
      margin: '0 auto'
    }}>
        <button onClick={() => setCurrentIdx(prev => Math.max(0, prev - 1))} disabled={currentIdx === 0} className="back-button" style={{
        padding: '10px 20px',
        border: '1px solid var(--clr-border)',
        borderRadius: '6px',
        cursor: currentIdx === 0 ? 'not-allowed' : 'pointer'
      }}>
          ← Prev
        </button>

        {currentIdx < 14 ? <button onClick={() => setCurrentIdx(prev => prev + 1)} className="submit-btn" style={{
        width: 'auto',
        padding: '10px 24px'
      }}>
            Next →
          </button> : <button onClick={handleSubmit} disabled={submitting} className="submit-btn" style={{
        width: 'auto',
        padding: '10px 24px',
        background: 'orange',
        borderColor: 'orange',
        color: '#000',
        fontWeight: 'bold'
      }}>
            {submitting ? 'Submitting...' : 'Finish Checkpoint'}
          </button>}
      </div>
    </div>;
}

// ─────────────────────────────────────────────────────────────────────────────
// ProgressTrackerApp — Gym Quiz History Visualization
// ─────────────────────────────────────────────────────────────────────────────
function ProgressTrackerApp({
  onBack
}) {
  const [selectedGym, setSelectedGym] = useState(SUPPORTED_GYMS[0]);
  const [page, setPage] = useState(0);
  const [selectedPoint, setSelectedPoint] = useState(null);
  const [allHistory, setAllHistory] = useState([]);
  useEffect(() => {
    setAllHistory(loadHistory());
  }, []);
  const gymRecords = useMemo(() => allHistory.filter(r => r.gymName === selectedGym), [allHistory, selectedGym]);
  const sortedRecords = useMemo(() => [...gymRecords].sort((a, b) => new Date(b.date) - new Date(a.date)), [gymRecords]);
  const totalSessions = gymRecords.length;
  const avgAccuracy = totalSessions > 0 ? parseFloat((gymRecords.reduce((s, r) => s + r.accuracy, 0) / totalSessions).toFixed(1)) : 0;
  const bestAccuracy = totalSessions > 0 ? parseFloat(Math.max(...gymRecords.map(r => r.accuracy)).toFixed(1)) : 0;
  const avgSpeed = totalSessions > 0 ? parseFloat((gymRecords.reduce((s, r) => s + r.correctAnswers * 60 / r.timeTakenSeconds, 0) / totalSessions).toFixed(1)) : 0;
  const accelData = gymRecords.slice().reverse().map((r, i) => ({
    session: i + 1,
    accuracy: r.accuracy,
    record: r
  }));
  const speedData = gymRecords.slice().reverse().map((r, i) => {
    const spd = r.timeTakenSeconds > 0 ? parseFloat((r.correctAnswers * 60 / r.timeTakenSeconds).toFixed(1)) : 0;
    return {
      session: i + 1,
      speed: spd,
      record: r
    };
  });
  const yPadding = (min, max) => {
    const range = max - min;
    return Math.max(1, range * 0.15);
  };
  const accelDomain = accelData.length > 0 ? [Math.max(0, Math.min(...accelData.map(d => d.accuracy)) - yPadding(Math.min(...accelData.map(d => d.accuracy)), Math.max(...accelData.map(d => d.accuracy)))), Math.min(100, Math.max(...accelData.map(d => d.accuracy)) + yPadding(Math.min(...accelData.map(d => d.accuracy)), Math.max(...accelData.map(d => d.accuracy))))] : [0, 100];
  const speedMin = speedData.length > 0 ? Math.min(...speedData.map(d => d.speed)) : 0;
  const speedMax = speedData.length > 0 ? Math.max(...speedData.map(d => d.speed)) : 5;
  const speedDomain = [Math.max(0, speedMin - yPadding(speedMin, speedMax)), speedMax + yPadding(speedMin, speedMax)];
  const makeChartOptions = (yLabel, ySuffix, yMin, yMax) => ({
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        display: false
      },
      tooltip: {
        backgroundColor: 'var(--clr-surface)',
        titleColor: 'var(--clr-text)',
        bodyColor: 'var(--clr-text)',
        borderColor: 'var(--clr-border)',
        borderWidth: 1,
        padding: 10,
        displayColors: false,
        callbacks: {
          label: context => {
            const value = context.parsed.y;
            return ySuffix ? `${value}${ySuffix}` : `${value}`;
          }
        }
      }
    },
    interaction: {
      mode: 'index',
      intersect: false
    },
    scales: {
      x: {
        title: {
          display: true,
          text: 'Session Number',
          color: 'var(--clr-dim)'
        },
        ticks: {
          color: 'var(--clr-dim)',
          font: {
            size: 13
          }
        },
        grid: {
          color: 'rgba(0, 0, 0, 0.08)'
        }
      },
      y: {
        min: yMin,
        max: yMax,
        title: {
          display: true,
          text: yLabel,
          color: 'var(--clr-dim)'
        },
        ticks: {
          color: 'var(--clr-dim)',
          font: {
            size: 13
          },
          callback: v => ySuffix ? `${v}${ySuffix}` : `${v}`
        },
        grid: {
          color: 'rgba(0, 0, 0, 0.08)'
        }
      }
    }
  });
  const accuracyChartData = {
    labels: accelData.map(d => d.session),
    datasets: [{
      label: 'Accuracy (%)',
      data: accelData.map(d => d.accuracy),
      borderColor: '#4caf50',
      backgroundColor: 'rgba(76, 175, 80, 0.2)',
      pointRadius: 4,
      pointHoverRadius: 6,
      tension: 0.4,
      fill: false
    }]
  };
  const speedChartData = {
    labels: speedData.map(d => d.session),
    datasets: [{
      label: 'Correct answers/min',
      data: speedData.map(d => d.speed),
      borderColor: '#2196f3',
      backgroundColor: 'rgba(33, 150, 243, 0.2)',
      pointRadius: 4,
      pointHoverRadius: 6,
      tension: 0.4,
      fill: false
    }]
  };
  const accuracyChartOptions = makeChartOptions('Accuracy (%)', '%', accelDomain[0], accelDomain[1]);
  const speedChartOptions = makeChartOptions('Correct answers/min', '', speedDomain[0], speedDomain[1]);
  const PAGE_SIZE = 20;
  const paginated = sortedRecords.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE);
  const formatDate = iso => {
    const d = new Date(iso);
    const dd = String(d.getDate()).padStart(2, '0');
    const mo = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'][d.getMonth()];
    const yy = d.getFullYear();
    const hh = String(d.getHours()).padStart(2, '0');
    const mm = String(d.getMinutes()).padStart(2, '0');
    return `${dd}-${mo}-${yy} ${hh}:${mm}`;
  };
  return <>
      <div className="header-row">
        <button className="back-button" onClick={onBack}>← Home</button>
      </div>
      <h1>Track Progress</h1>

      <div style={{
      marginBottom: 20
    }}>
        <label style={{
        display: 'block',
        fontWeight: 600,
        marginBottom: 6
      }}>Select Gym to Plot</label>
        <select value={selectedGym} onChange={e => {
        setSelectedGym(e.target.value);
        setPage(0);
        setSelectedPoint(null);
      }} style={{
        width: '100%',
        padding: '8px 12px',
        borderRadius: 6,
        background: 'var(--clr-surface)',
        color: 'var(--clr-text)',
        border: '1px solid var(--clr-border)',
        fontSize: '0.95rem'
      }}>
          {SUPPORTED_GYMS.map(g => <option key={g} value={g}>{g}</option>)}
        </select>
      </div>

      {totalSessions === 0 ? <div style={{
      textAlign: 'center',
      padding: '3rem 1rem',
      color: 'var(--clr-dim)'
    }}>
          <div style={{
        fontSize: '1.1rem',
        marginBottom: 8
      }}>No progress history available for this Gym yet.</div>
          <div>Complete a quiz to start tracking progress.</div>
        </div> : <>
          {/* Summary Stats */}
          <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))',
        gap: 12,
        marginBottom: 24
      }}>
            <div style={{
          background: 'var(--clr-card)',
          border: '1px solid var(--clr-border)',
          borderRadius: 8,
          padding: '14px 16px',
          textAlign: 'center'
        }}>
              <div style={{
            fontSize: '0.8rem',
            color: 'var(--clr-dim)',
            marginBottom: 4
          }}>Total Sessions</div>
              <div style={{
            fontSize: '1.5rem',
            fontWeight: 700
          }}>{totalSessions}</div>
            </div>
            <div style={{
          background: 'var(--clr-card)',
          border: '1px solid var(--clr-border)',
          borderRadius: 8,
          padding: '14px 16px',
          textAlign: 'center'
        }}>
              <div style={{
            fontSize: '0.8rem',
            color: 'var(--clr-dim)',
            marginBottom: 4
          }}>Average Accuracy</div>
              <div style={{
            fontSize: '1.5rem',
            fontWeight: 700
          }}>{avgAccuracy}%</div>
            </div>
            <div style={{
          background: 'var(--clr-card)',
          border: '1px solid var(--clr-border)',
          borderRadius: 8,
          padding: '14px 16px',
          textAlign: 'center'
        }}>
              <div style={{
            fontSize: '0.8rem',
            color: 'var(--clr-dim)',
            marginBottom: 4
          }}>Best Accuracy</div>
              <div style={{
            fontSize: '1.5rem',
            fontWeight: 700
          }}>{bestAccuracy}%</div>
            </div>
            <div style={{
          background: 'var(--clr-card)',
          border: '1px solid var(--clr-border)',
          borderRadius: 8,
          padding: '14px 16px',
          textAlign: 'center'
        }}>
              <div style={{
            fontSize: '0.8rem',
            color: 'var(--clr-dim)',
            marginBottom: 4
          }}>Avg Speed</div>
              <div style={{
            fontSize: '1.5rem',
            fontWeight: 700
          }}>{avgSpeed}/min</div>
            </div>
          </div>

          {/* Accuracy Graph */}
          <div style={{
        background: 'var(--clr-card)',
        border: '1px solid var(--clr-border)',
        borderRadius: 10,
        padding: '16px',
        marginBottom: 16
      }}>
            <div style={{
          fontSize: '1.05rem',
          fontWeight: 600,
          marginBottom: 12
        }}>Accuracy vs Session Number</div>
            <div style={{
          width: '100%',
          height: 220
        }}>
              <Line data={accuracyChartData} options={accuracyChartOptions} />
            </div>
          </div>

          {/* Speed Graph */}
          <div style={{
        background: 'var(--clr-card)',
        border: '1px solid var(--clr-border)',
        borderRadius: 10,
        padding: '16px',
        marginBottom: 16
      }}>
            <div style={{
          fontSize: '1.05rem',
          fontWeight: 600,
          marginBottom: 12
        }}>Speed vs Session Number</div>
            <div style={{
          width: '100%',
          height: 220
        }}>
              <Line data={speedChartData} options={speedChartOptions} />
            </div>
          </div>

          {/* Session Table */}
          <div style={{
        overflowX: 'auto'
      }}>
            <table style={{
          width: '100%',
          borderCollapse: 'collapse',
          fontSize: '0.88rem'
        }}>
              <thead>
                <tr style={{
              background: 'var(--clr-card)',
              borderBottom: '2px solid var(--clr-border)'
            }}>
                  <th style={{
                padding: '8px 10px',
                textAlign: 'left',
                color: 'var(--clr-dim)'
              }}>Date</th>
                  <th style={{
                padding: '8px 10px',
                textAlign: 'center',
                color: 'var(--clr-dim)'
              }}>Easy</th>
                  <th style={{
                padding: '8px 10px',
                textAlign: 'center',
                color: 'var(--clr-dim)'
              }}>Medium</th>
                  <th style={{
                padding: '8px 10px',
                textAlign: 'center',
                color: 'var(--clr-dim)'
              }}>Hard</th>
                  <th style={{
                padding: '8px 10px',
                textAlign: 'center',
                color: 'var(--clr-dim)'
              }}>Total</th>
                  <th style={{
                padding: '8px 10px',
                textAlign: 'center',
                color: 'var(--clr-dim)'
              }}>Correct</th>
                  <th style={{
                padding: '8px 10px',
                textAlign: 'center',
                color: 'var(--clr-dim)'
              }}>Accuracy</th>
                  <th style={{
                padding: '8px 10px',
                textAlign: 'center',
                color: 'var(--clr-dim)'
              }}>Correct/min</th>
                </tr>
              </thead>
              <tbody>
                {paginated.map(r => {
              const spd = r.timeTakenSeconds > 0 ? parseFloat((r.correctAnswers * 60 / r.timeTakenSeconds).toFixed(1)) : 0;
              return <tr key={r.id} onClick={() => setSelectedPoint({
                record: r,
                session: sortedRecords.indexOf(r) + 1
              })} style={{
                borderBottom: '1px solid var(--clr-border)',
                cursor: 'pointer'
              }}>
                      <td style={{
                  padding: '8px 10px'
                }}>{formatDate(r.date)}</td>
                      <td style={{
                  padding: '8px 10px',
                  textAlign: 'center'
                }}>{r.questionSummary?.easy || 0}</td>
                      <td style={{
                  padding: '8px 10px',
                  textAlign: 'center'
                }}>{r.questionSummary?.medium || 0}</td>
                      <td style={{
                  padding: '8px 10px',
                  textAlign: 'center'
                }}>{r.questionSummary?.hard || 0}</td>
                      <td style={{
                  padding: '8px 10px',
                  textAlign: 'center'
                }}>{r.totalQuestions}</td>
                      <td style={{
                  padding: '8px 10px',
                  textAlign: 'center'
                }}>{r.correctAnswers}</td>
                      <td style={{
                  padding: '8px 10px',
                  textAlign: 'center',
                  fontWeight: 600,
                  color: r.accuracy >= 80 ? '#4caf50' : r.accuracy >= 50 ? '#ff9800' : '#f44336'
                }}>{r.accuracy}%</td>
                      <td style={{
                  padding: '8px 10px',
                  textAlign: 'center'
                }}>{spd}</td>
                    </tr>;
            })}
              </tbody>
            </table>
          </div>

          {/* Pagination */}
          {totalSessions > PAGE_SIZE && <div style={{
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        gap: 16,
        marginTop: 16
      }}>
              <button onClick={() => setPage(p => Math.max(0, p - 1))} disabled={page === 0} style={{
          padding: '6px 16px',
          borderRadius: 6,
          background: 'var(--clr-card)',
          border: '1px solid var(--clr-border)',
          color: 'var(--clr-text)',
          cursor: page === 0 ? 'not-allowed' : 'pointer',
          opacity: page === 0 ? 0.4 : 1
        }}>
                Previous
              </button>
              <span style={{
          color: 'var(--clr-dim)',
          fontSize: '0.9rem'
        }}>
                Page {page + 1} of {Math.ceil(totalSessions / PAGE_SIZE)}
              </span>
              <button onClick={() => setPage(p => Math.min(Math.ceil(totalSessions / PAGE_SIZE) - 1, p + 1))} disabled={page >= Math.ceil(totalSessions / PAGE_SIZE) - 1} style={{
          padding: '6px 16px',
          borderRadius: 6,
          background: 'var(--clr-card)',
          border: '1px solid var(--clr-border)',
          color: 'var(--clr-text)',
          cursor: page >= Math.ceil(totalSessions / PAGE_SIZE) - 1 ? 'not-allowed' : 'pointer',
          opacity: page >= Math.ceil(totalSessions / PAGE_SIZE) - 1 ? 0.4 : 1
        }}>
                Next
              </button>
            </div>}
        </>}
    </>;
}

// Export main App component (entry point)

// Named export so main.jsx can render the global hamburger menu next to <App />

function GenericLabApp({
  title,
  subtitle,
  endpoint,
  onBack,
  renderQuestionCustom,
  customGenerate,
  initialDifficulty,
  initialNumQuestions,
  initialStarted
}) {
  const [difficulty, setDifficulty] = useState(initialDifficulty || 'easy');
  const [numQuestions, setNumQuestions] = useState(initialNumQuestions || '5');
  const [started, setStarted] = useState(initialStarted || false);
  const [finished, setFinished] = useState(false);
  const [question, setQuestion] = useState(null);
  const [answer, setAnswer] = useState('');
  const [score, setScore] = useState(0);
  const [questionNumber, setQuestionNumber] = useState(0);
  const [totalQ, setTotalQ] = useState(5);
  const [feedback, setFeedback] = useState('');
  const [isCorrect, setIsCorrect] = useState(null);
  const [loading, setLoading] = useState(false);
  const [revealed, setRevealed] = useState(false);
  const [results, setResults] = useState([]);
  const timer = useTimer();
  // Guard ref: prevents double-fetch from React StrictMode concurrent effect invocations
  const fetchingRef = useRef(false);
  // Prefetch cache: holds the next question already fetched silently in background
  const prefetchRef = useRef(null);
  const fetchQuestion = async () => {
    if (fetchingRef.current) return;
    fetchingRef.current = true;
    if (questionNumber >= totalQ) {
      fetchingRef.current = false;
      setFinished(true);
      timer.reset();
      return;
    }
    setLoading(true);
    setFeedback('');
    setAnswer('');
    setRevealed(false);
    setIsCorrect(null);

    // Use prefetched question if available for instant load, otherwise fetch now
    let data = prefetchRef.current;
    prefetchRef.current = null;
    if (!data) {
      data = customGenerate ? await customGenerate() : await (await fetch(`${API}${endpoint}/generate?difficulty=${difficulty}`)).json();
    }
    setQuestion(data);
    setQuestionNumber(n => n + 1);
    setLoading(false);
    fetchingRef.current = false;
    timer.start();
    // Silently prefetch the next question in background while user answers
    const doFetch = customGenerate ? customGenerate : () => fetch(`${API}${endpoint}/generate?difficulty=${difficulty}`).then(r => r.json());
    doFetch().then(next => {
      if (next) prefetchRef.current = next;
    }).catch(() => {});
  };
  const startQuiz = () => {
    setTotalQ(Number(numQuestions) || 5);
    setStarted(true);
    setFinished(false);
    setScore(0);
    setQuestionNumber(0);
    setResults([]);
    fetchingRef.current = false;
    prefetchRef.current = null;
    // Will trigger fetchQuestion via useEffect
  };
  useEffect(() => {
    if (started && !finished && questionNumber === 0) {
      fetchQuestion();
    }
  }, [started, finished, questionNumber]);
  const submitAns = async optAns => {
    if (!question || revealed) return;
    const finalAns = optAns !== undefined ? optAns : answer;
    const timeTaken = timer.stop();
    setAnswer(finalAns);
    const res = await fetch(`${API}${endpoint}/check`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        answerOption: finalAns,
        expected: question.answer
      })
    });
    const data = await res.json();
    setIsCorrect(data.correct);
    if (data.correct) setScore(s => s + 1);
    const explanationText = question.hint ? ` (${question.hint})` : '';
    setFeedback(data.correct ? `Correct! The answer is ${data.correctAnswer}.${explanationText}` : `Incorrect. The correct answer is ${data.correctAnswer}.${explanationText}`);
    setResults(prev => [...prev, {
      question: question.prompt,
      userAnswer: finalAns,
      correctAnswer: data.correctAnswer,
      correct: data.correct,
      time: timeTaken
    }]);
    setRevealed(true);
  };
  const handleSolve = async () => {
    if (revealed) return;
    const timeTaken = timer.stop();
    const res = await fetch(`${API}${endpoint}/check`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        answerOption: '',
        expected: question.answer,
        solve: true
      })
    });
    const data = await res.json();
    setIsCorrect(false);
    const explanationText = question.hint ? ` (${question.hint})` : '';
    setFeedback(`Solution: ${data.correctAnswer}.${explanationText}`);
    setResults(prev => [...prev, {
      question: question.prompt,
      userAnswer: '—',
      correctAnswer: data.correctAnswer,
      correct: false,
      time: timeTaken
    }]);
    setRevealed(true);
  };
  const handleSubmitOrNext = () => {
    if (!revealed) {
      if (answer || question.options) submitAns();
    } else {
      fetchQuestion();
    }
  };
  const advanceRef = useRef(() => {});
  advanceRef.current = () => fetchQuestion();
  useAutoAdvance(revealed, advanceRef, isCorrect);
  useProgressSubmit(revealed, isCorrect, endpoint.split('/')[1], question?.id);
  const C = {
    bg: '#1A1A1A',
    card: 'rgb(44, 38, 34)',
    text: '#FFFFFF',
    muted: '#A0A0A0',
    orange: '#F97316',
    orange2: '#EA580C',
    border: '#333333'
  };
  const FONT = "'Nunito', sans-serif";

  // Reusable Floating Background for the Dark Theme Start Screen
  const BG_SYMS = ['×', '÷', '+', '=', '%', 'π', '√', '∑', '3', '5', '9'];
  const itemsRef = useRef(Array.from({
    length: 16
  }, (_, i) => ({
    id: i,
    sym: BG_SYMS[i % BG_SYMS.length],
    x: Math.random() * 100,
    y: Math.random() * 100,
    size: 11 + Math.random() * 18,
    delay: Math.random() * 8,
    dur: 12 + Math.random() * 10
  })));
  if (!started && !finished) {
    return <div style={{
      minHeight: '100vh',
      background: '#181512',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '24px',
      fontFamily: 'Inter, sans-serif'
    }}>
        <div style={{
        background: '#2D2520',
        border: '1.5px solid #4A4038',
        borderRadius: '28px',
        boxShadow: '0 20px 40px rgba(0,0,0,.45)',
        padding: '48px 40px',
        maxWidth: '720px',
        width: '100%',
        textAlign: 'center',
        position: 'relative'
      }}>
          <button onClick={onBack} style={{
          position: 'absolute',
          top: '24px',
          left: '24px',
          background: 'transparent',
          border: '1px solid #5B5048',
          borderRadius: '6px',
          padding: '6px 14px',
          color: '#A89C93',
          fontFamily: 'Inter, sans-serif',
          fontWeight: 600,
          fontSize: '0.85rem',
          cursor: 'pointer'
        }}>← Home</button>

          <h1 style={{
          fontFamily: 'Georgia, "Times New Roman", serif',
          fontWeight: 700,
          fontSize: '48px',
          color: '#F4F1ED',
          margin: '0 0 12px',
          lineHeight: 1.1
        }}>
            {title.replace('🔷 ', '')}
          </h1>
          <p style={{
          color: '#988D84',
          fontSize: '0.9rem',
          margin: '0 0 40px',
          fontFamily: 'Inter, sans-serif',
          fontWeight: 400
        }}>
            {subtitle}
          </p>
          <p style={{
          color: '#988D84',
          fontSize: '0.9rem',
          margin: '0 0 24px',
          fontFamily: 'Inter, sans-serif',
          fontWeight: 400
        }}>
            Practice {title.toLowerCase().replace('🔷 ', '')}!
          </p>

          <div style={{
          marginBottom: '24px'
        }}>
            <h3 style={{
            color: '#F4F1ED',
            fontSize: '0.9rem',
            margin: '0 0 16px',
            fontFamily: 'Inter, sans-serif',
            fontWeight: 700
          }}>
              Select Difficulty:
            </h3>
            <div style={{
            display: 'flex',
            gap: '12px',
            justifyContent: 'center',
            flexWrap: 'wrap',
            marginBottom: '12px'
          }}>
              {[['Easy', 'easy'], ['Medium', 'medium'], ['Hard', 'hard']].map(([lbl, val]) => <button key={val} onClick={() => setDifficulty(val)} style={{
              background: difficulty === val ? '#F08C46' : 'transparent',
              border: difficulty === val ? '1px solid #F08C46' : '1px solid #5B5048',
              borderRadius: '50px',
              padding: '8px 16px',
              color: difficulty === val ? '#FFF' : '#988D84',
              fontFamily: 'Inter, sans-serif',
              fontWeight: 600,
              fontSize: '0.85rem',
              cursor: 'pointer'
            }}>
                  {lbl}
                </button>)}
            </div>
          </div>

          <div style={{
          marginBottom: '32px',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center'
        }}>
            <label style={{
            color: '#988D84',
            fontSize: '0.85rem',
            margin: '0 0 12px',
            fontFamily: 'Inter, sans-serif',
            fontWeight: 400
          }}>
              How many questions?
            </label>
            <input type="text" value={numQuestions} onChange={e => {
            const v = e.target.value;
            if (v === '' || /^\d+$/.test(v)) setNumQuestions(v);
          }} style={{
            background: '#463B34',
            border: '1px solid #5B5048',
            borderRadius: '6px',
            padding: '10px',
            color: '#FFF',
            fontFamily: 'Inter, sans-serif',
            fontWeight: 600,
            fontSize: '0.9rem',
            width: '100px',
            textAlign: 'center',
            outline: 'none'
          }} placeholder="5" />
          </div>

          <button onClick={startQuiz} style={{
          background: '#F08C46',
          border: 'none',
          borderRadius: '6px',
          padding: '10px 24px',
          color: '#FFF',
          fontFamily: 'Inter, sans-serif',
          fontWeight: 600,
          fontSize: '0.9rem',
          cursor: 'pointer'
        }}>
            Start Quiz
          </button>
        </div>
      </div>;
  }
  return <div className="kid-zone">
      {started && !finished && <div className="kid-card">
          <div className="kid-status-row">
            <button className="kid-back-btn" onClick={onBack}>← Back</button>
            <span>Question {questionNumber} of {totalQ}</span>
            {timer && <div className="kid-timer">⏱️ {timer.elapsed}s</div>}
          </div>
          <div className="kid-progress-bar">
            <div className="kid-progress-fill" style={{
          width: `${questionNumber / totalQ * 100}%`
        }}></div>
          </div>

          <div className="question-box" style={{
        fontSize: '1.8rem',
        margin: '20px 0',
        textAlign: 'center',
        fontFamily: 'Nunito, sans-serif'
      }}>
            {loading || !question ? 'Loading...' : question.prompt}
          </div>

          {question && !loading && renderQuestionCustom && renderQuestionCustom(question, answer, setAnswer, submitAns, revealed)}

          {question && !loading && !renderQuestionCustom && question.options && <div className="emoji-container" style={{
        gap: '15px'
      }}>
              {question.options.map(opt => <button key={opt} className={`kid-btn-choice ${answer === String(opt) ? 'selected' : ''}`} onClick={() => !revealed && setAnswer(String(opt))} disabled={revealed}>
                  {opt}
                </button>)}
            </div>}

          {question && !loading && !renderQuestionCustom && !question.options && <div style={{
        textAlign: 'center',
        marginBottom: '30px'
      }}>
              <input type="text" className="fun-input" value={answer} onChange={e => !revealed && setAnswer(e.target.value)} onKeyDown={e => {
          if (e.key === 'Enter') handleSubmitOrNext();
        }} placeholder="?" disabled={revealed} autoFocus />
            </div>}

          {renderFeedback(feedback, isCorrect)}
          <div className="button-row" style={{
        marginTop: '30px'
      }}>
            {!revealed ? <div style={{
          display: 'flex',
          gap: '10px',
          width: '100%'
        }}>
                <button className="kid-btn-primary" onClick={handleSolve} style={{
            flex: 1,
            opacity: 0.75
          }}>Show Answer</button>
                <button className="kid-btn-primary" onClick={() => submitAns()} disabled={loading || !answer && !question?.options} style={{
            flex: 1
          }}>Submit</button>
              </div> : <button className="kid-btn-primary" onClick={handleSubmitOrNext}>{questionNumber >= totalQ ? 'Finish Lab 🏁' : 'Next Question ➡️'}</button>}
          </div>
          {results.length > 0 && <ResultsTable results={results} />}
        </div>}

      {finished && <div className="kid-card" style={{
      marginTop: '5vh',
      textAlign: 'center'
    }}>
          <div className="bouncy-emoji" style={{
        marginBottom: '20px'
      }}>🎉</div>
          <h1 style={{
        fontSize: '3rem'
      }}>Lab Complete!</h1>
          <p style={{
        fontSize: '1.5rem',
        fontWeight: 'bold',
        color: 'var(--kid-success)'
      }}>Final score: {score} / {totalQ}</p>
          <div style={{
        marginTop: '30px'
      }}>
            <ResultsTable results={results} />
          </div>
          <div className="button-row" style={{
        marginTop: '30px'
      }}>
            <button className="kid-btn-primary" onClick={() => {
          setStarted(false);
          setFinished(false);
        }}>Play Again 🔄</button>
            <button className="kid-back-btn" onClick={onBack} style={{
          marginLeft: '15px'
        }}>← Back to Home</button>
          </div>
        </div>}
    </div>;
}
function BasicArithmeticLabApp({
  onBack
}) {
  const renderCustom = (q, ans, setAns, submitAns, revealed) => {
    if (q.template === 'missing_number' || q.template === 'greater_smaller') {
      const parts = q.prompt.split(' ');
      return <div className="math-bubble-row">
          {parts.map((p, i) => {
          if (p === '?' || p === '__') {
            return <input key={i} type="text" className="fun-input" value={ans} onChange={e => !revealed && setAns(e.target.value)} placeholder="?" disabled={revealed} autoFocus />;
          }
          if (['×', '÷', '+', '-', '=', '>', '<'].includes(p)) {
            return <span key={i} className="math-bubble op">{p}</span>;
          }
          return <span key={i} className="math-bubble">{p}</span>;
        })}
        </div>;
    }
    if (q.template === 'true_false') {
      const eq = q.prompt.replace('Is ', '').replace(' ?', '').split(' ');
      return <div style={{
        textAlign: 'center'
      }}>
          <div className="math-bubble-row" style={{
          marginBottom: '10px'
        }}>
            {eq.map((p, i) => {
            if (['×', '÷', '+', '-', '='].includes(p)) return <span key={i} className="math-bubble op">{p}</span>;
            return <span key={i} className="math-bubble">{p}</span>;
          })}
          </div>
          <p style={{
          fontSize: '2rem',
          fontFamily: 'Quicksand, sans-serif',
          color: 'var(--kid-secondary)'
        }}>True or False?</p>
          <div className="emoji-container" style={{
          gap: '20px'
        }}>
            <button className={`kid-btn-choice ${ans === 'True' ? 'selected' : ''}`} onClick={() => !revealed && setAns('True')} disabled={revealed} style={{
            fontSize: '2rem'
          }}>👍 True</button>
            <button className={`kid-btn-choice ${ans === 'False' ? 'selected' : ''}`} onClick={() => !revealed && setAns('False')} disabled={revealed} style={{
            fontSize: '2rem'
          }}>👎 False</button>
          </div>
        </div>;
    }
    return <div style={{
      textAlign: 'center',
      marginBottom: '30px'
    }}>
        <p style={{
        fontSize: '2.5rem',
        fontFamily: 'Quicksand, sans-serif',
        color: 'var(--kid-secondary)',
        lineHeight: 1.4
      }}>{q.prompt}</p>
        {!q.options && <input type="text" className="fun-input" value={ans} onChange={e => !revealed && setAns(e.target.value)} placeholder="?" disabled={revealed} autoFocus />}
      </div>;
  };
  return <GenericLabApp title="Origin" subtitle="Mixed multiplication & division templates" endpoint="/api/basic-arithmetic-lab" onBack={onBack} renderQuestionCustom={renderCustom} />;
}
function MensurationLabApp({
  onBack,
  initialDifficulty,
  initialNumQuestions,
  initialStarted
}) {
  const renderCustom = (q, ans, setAns, submitAns, revealed) => {
    // ── COUNT SIDES / SHAPE NAME ──────────────────────────────────────────
    if (q.template === 'count_sides' || q.template === 'shape_name') {
      const sides = q.sides;
      const color = q.color || '#FF6B6B';
      const pts = Array.from({
        length: sides
      }).map((_, i) => {
        const angle = i * 2 * Math.PI / sides - Math.PI / 2;
        return `${50 + 40 * Math.cos(angle)},${50 + 40 * Math.sin(angle)}`;
      }).join(' ');
      return <div className="men-canvas">
          <div className="men-shape-wrapper">
            <svg viewBox="0 0 100 100" className="men-shape-svg">
              <defs>
                <linearGradient id={`sg${sides}`} x1="0%" y1="0%" x2="100%" y2="100%">
                  <stop offset="0%" stopColor={color} stopOpacity="0.9" />
                  <stop offset="100%" stopColor={color} stopOpacity="0.5" />
                </linearGradient>
              </defs>
              <polygon points={pts} fill={`url(#sg${sides})`} stroke="white" strokeWidth="3" />
              {Array.from({
              length: sides
            }).map((_, i) => {
              const angle = i * 2 * Math.PI / sides - Math.PI / 2;
              return <circle key={i} cx={50 + 40 * Math.cos(angle)} cy={50 + 40 * Math.sin(angle)} r="3.5" fill="white" opacity="0.9" />;
            })}
            </svg>
          </div>
          <div className="men-options-grid">
            {q.options?.map(opt => <button key={opt} className={`men-choice-btn ${ans === opt ? 'selected' : ''}`} onClick={() => !revealed && setAns(opt)} disabled={revealed}>
                {opt}{revealed && String(opt) === String(q.answer) && <span className="men-correct-tick"> ✓</span>}
              </button>)}
          </div>
        </div>;
    }

    // ── AREA GRID (interactive tap-to-count) ─────────────────────────────
    if (q.template === 'area_grid') {
      const counted = typeof ans === 'string' && ans.startsWith('[') ? JSON.parse(ans) : [];
      const setCounted = updater => {
        const next = typeof updater === 'function' ? updater(counted) : updater;
        setAns(JSON.stringify(next));
      };
      const allCount = q.w * q.h;
      const handleCellClick = idx => {
        if (revealed) return;
        setCounted(prev => {
          const next = prev.includes(idx) ? prev.filter(i => i !== idx) : [...prev, idx];
          if (next.length === allCount) setTimeout(() => setAns(String(allCount)), 100);
          return next;
        });
      };
      return <div className="men-canvas" style={{
        flexDirection: 'column',
        gap: '16px'
      }}>
          <p className="men-canvas-tip">👆 Tap each square to count it!</p>
          <div className="men-grid-wrap" style={{
          gridTemplateColumns: `repeat(${q.w}, 1fr)`
        }}>
            {Array.from({
            length: allCount
          }).map((_, i) => <div key={i} className={`men-grid-cell ${counted.includes(i) ? 'counted' : ''} ${revealed ? 'revealed' : ''}`} onClick={() => handleCellClick(i)}>
                {counted.includes(i) || revealed ? '✓' : ''}
              </div>)}
          </div>
          <div className="men-cell-count-pill">
            {revealed ? `✅ Area = ${q.answer} sq units` : `${counted.length} / ${allCount} counted`}
          </div>
        </div>;
    }

    // ── PERIMETER BLOCKS (animated walking dot) ───────────────────────────
    if (q.template === 'perimeter_blocks') {
      const cellPx = 44;
      const svgW = (q.w + 2) * cellPx;
      const svgH = (q.h + 2) * cellPx;
      const ox = cellPx;
      const oy = cellPx;
      const rw = q.w * cellPx;
      const rh = q.h * cellPx;
      return <div className="men-canvas" style={{
        flexDirection: 'column',
        gap: '16px'
      }}>
          <svg width={svgW} height={svgH} style={{
          maxWidth: '100%'
        }}>
            <defs>
              <pattern id="gridP" width={cellPx} height={cellPx} patternUnits="userSpaceOnUse">
                <path d={`M ${cellPx} 0 L 0 0 0 ${cellPx}`} fill="none" stroke="#E2E8F0" strokeWidth="1" />
              </pattern>
            </defs>
            <rect x={ox} y={oy} width={rw} height={rh} fill="url(#gridP)" />
            <rect x={ox} y={oy} width={rw} height={rh} fill="rgba(232,134,74,0.08)" stroke="#e8864a" strokeWidth="3" rx="4" />
            <text x={ox + rw / 2} y={oy - 10} textAnchor="middle" fill="#e8864a" fontWeight="bold" fontSize="14">{q.w} units</text>
            <text x={ox + rw + 16} y={oy + rh / 2 + 5} textAnchor="middle" fill="#e8864a" fontWeight="bold" fontSize="14" transform={`rotate(90 ${ox + rw + 16} ${oy + rh / 2 + 5})`}>{q.h} units</text>
            {revealed ? <rect x={ox} y={oy} width={rw} height={rh} fill="none" stroke="#48BB78" strokeWidth="4" rx="4" strokeDasharray="10 4" /> : <circle r="7" fill="#FF7E67">
                <animateMotion dur={`${(q.w + q.h) * 0.4}s`} repeatCount="indefinite" path={`M ${ox},${oy} L ${ox + rw},${oy} L ${ox + rw},${oy + rh} L ${ox},${oy + rh} Z`} />
              </circle>}
          </svg>
          <div className="men-options-grid">
            {q.options?.map(opt => <button key={opt} className={`men-choice-btn ${ans === opt ? 'selected' : ''}`} onClick={() => !revealed && setAns(opt)} disabled={revealed}>
                {opt}{revealed && String(opt) === String(q.answer) && <span className="men-correct-tick"> ✓</span>}
              </button>)}
          </div>
        </div>;
    }

    // ── COMPARE AREA ──────────────────────────────────────────────────────
    if (q.template === 'compare_area') {
      const scale = 36;
      return <div className="men-canvas" style={{
        flexDirection: 'column',
        gap: '20px'
      }}>
          <div style={{
          display: 'flex',
          gap: '30px',
          justifyContent: 'center',
          flexWrap: 'wrap',
          alignItems: 'flex-end'
        }}>
            {[q.shape1, q.shape2].map((sh, idx) => <div key={idx} style={{
            textAlign: 'center'
          }}>
                <div style={{
              width: `${sh.w * scale}px`,
              height: `${sh.h * scale}px`,
              background: sh.color || '#FF7E67',
              opacity: 0.85,
              borderRadius: '10px',
              boxShadow: `0 8px 20px ${sh.color || '#FF7E67'}55`,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              color: 'white',
              fontWeight: 800,
              fontSize: '1.2rem',
              fontFamily: 'Quicksand'
            }}>{sh.w}×{sh.h}</div>
                <div style={{
              marginTop: '10px',
              fontWeight: 800,
              fontSize: '1.4rem',
              color: sh.color,
              fontFamily: 'Quicksand'
            }}>Shape {sh.label}</div>
                <div style={{
              fontSize: '0.95rem',
              color: '#718096',
              fontFamily: 'Nunito'
            }}>
                  {revealed ? `Area = ${sh.w * sh.h}` : `${sh.w} × ${sh.h} = ?`}
                </div>
              </div>)}
          </div>
          <div className="men-options-grid" style={{
          gridTemplateColumns: 'repeat(3, 1fr)',
          maxWidth: '440px'
        }}>
            {q.options?.map(opt => <button key={opt} className={`men-choice-btn ${ans === opt ? 'selected' : ''}`} onClick={() => !revealed && setAns(opt)} disabled={revealed}>
                {opt}{revealed && opt === q.answer && <span className="men-correct-tick"> ✓</span>}
              </button>)}
          </div>
        </div>;
    }

    // ── RECT VS SQUARE ────────────────────────────────────────────────────
    if (q.template === 'rect_vs_square') {
      const isSquare = q.w === q.h;
      const scale = Math.min(45, 200 / Math.max(q.w, q.h));
      const rw = q.w * scale;
      const rh = q.h * scale;
      const ox = (280 - rw) / 2;
      const oy = (220 - rh) / 2;
      return <div className="men-canvas" style={{
        flexDirection: 'column',
        gap: '20px'
      }}>
          <svg width="280" height="220" style={{
          overflow: 'visible'
        }}>
            <defs>
              <linearGradient id="rectGrad" x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stopColor="#F6D365" /><stop offset="100%" stopColor="#FDA085" />
              </linearGradient>
            </defs>
            <rect x={ox} y={oy} width={rw} height={rh} fill="url(#rectGrad)" rx="8" className="men-rect-pulse" />
            <text x={ox + rw / 2} y={oy - 12} textAnchor="middle" fill="#E2E8F0" fontWeight="bold" fontSize="18">{q.w}</text>
            <text x={ox + rw + 16} y={oy + rh / 2 + 6} textAnchor="middle" fill="#E2E8F0" fontWeight="bold" fontSize="18">{q.h}</text>
            {isSquare && [`M ${ox + 8} ${oy} L ${ox + 8} ${oy + 8} L ${ox} ${oy + 8}`, `M ${ox + rw - 8} ${oy} L ${ox + rw - 8} ${oy + 8} L ${ox + rw} ${oy + 8}`, `M ${ox + rw - 8} ${oy + rh} L ${ox + rw - 8} ${oy + rh - 8} L ${ox + rw} ${oy + rh - 8}`, `M ${ox + 8} ${oy + rh} L ${ox + 8} ${oy + rh - 8} L ${ox} ${oy + rh - 8}`].map((d, i) => <path key={i} d={d} fill="none" stroke="white" strokeWidth="2" />)}
          </svg>
          <div className="men-options-grid" style={{
          gridTemplateColumns: 'repeat(2, 1fr)',
          maxWidth: '340px'
        }}>
            {q.options?.map(opt => <button key={opt} className={`men-choice-btn ${ans === opt ? 'selected' : ''}`} onClick={() => !revealed && setAns(opt)} disabled={revealed}>
                {opt === 'Square' ? '⬛' : '▬'} {opt}
                {revealed && opt === q.answer && <span className="men-correct-tick"> ✓</span>}
              </button>)}
          </div>
        </div>;
    }

    // ── TRIANGLE AREA ──────────────────────────────────────────────────────
    if (q.template === 'triangle_area') {
      const scale = Math.min(45, 200 / Math.max(q.base, q.height));
      const bPx = q.base * scale;
      const hPx = q.height * scale;
      const svgW = bPx + 80;
      const svgH = hPx + 70;
      const ox = 40;
      const oy = 30;
      const pts = `${ox},${oy + hPx} ${ox + bPx / 2},${oy} ${ox + bPx},${oy + hPx}`;
      return <div className="men-canvas" style={{
        flexDirection: 'column',
        gap: '20px'
      }}>
          <svg width={svgW} height={svgH} style={{
          maxWidth: '100%',
          overflow: 'visible'
        }}>
            <defs>
              <linearGradient id="triGrd" x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stopColor="#F6D365" /><stop offset="100%" stopColor="#FDA085" />
              </linearGradient>
            </defs>
            <polygon points={pts} fill="url(#triGrd)" stroke="white" strokeWidth="3" className="men-rect-pulse" />
            <line x1={ox + bPx / 2} y1={oy} x2={ox + bPx / 2} y2={oy + hPx} stroke="#2D2520" strokeWidth="2.5" strokeDasharray="5 3" opacity="0.85" />
            <path d={`M ${ox + bPx / 2 - 7} ${oy + hPx} L ${ox + bPx / 2 - 7} ${oy + hPx - 7} L ${ox + bPx / 2} ${oy + hPx - 7}`} fill="none" stroke="#2D2520" strokeWidth="1.5" opacity="0.85" />
            {/* Height Label Pill */}
            <rect x={ox + bPx / 2 + 8} y={oy + hPx / 2 - 12} width="52" height="22" rx="6" fill="#2D2520" stroke="#4A4038" strokeWidth="1.5" />
            <text x={ox + bPx / 2 + 34} y={oy + hPx / 2 + 4} textAnchor="middle" fill="#F4F1ED" fontWeight="bold" fontSize="13">h={q.height}</text>
            {/* Base Label Pill */}
            <rect x={ox + bPx / 2 - 38} y={oy + hPx + 14} width="76" height="22" rx="6" fill="#2D2520" stroke="#4A4038" strokeWidth="1.5" />
            <text x={ox + bPx / 2} y={oy + hPx + 30} textAnchor="middle" fill="#F4F1ED" fontWeight="bold" fontSize="13">base={q.base}</text>
          </svg>
          <div className="men-options-grid">
            {q.options?.map(opt => <button key={opt} className={`men-choice-btn ${ans === opt ? 'selected' : ''}`} onClick={() => !revealed && setAns(opt)} disabled={revealed}>
                {opt}{revealed && String(opt) === String(q.answer) && <span className="men-correct-tick"> ✓</span>}
              </button>)}
          </div>
        </div>;
    }

    // ── ANGLE TYPE ─────────────────────────────────────────────────────────
    if (q.template === 'angle_type') {
      const deg = q.degrees;
      const rad = deg * Math.PI / 180;
      const r = 90;
      const cx = 110;
      const cy = 120;
      const x2 = cx + r * Math.cos(-rad);
      const y2 = cy + r * Math.sin(-rad);
      const arcR = 50;
      const ax = cx + arcR * Math.cos(-rad);
      const ay = cy + arcR * Math.sin(-rad);
      const largeArc = deg > 180 ? 1 : 0;
      const arcColor = deg < 90 ? '#48BB78' : deg === 90 ? '#4ECDC4' : '#FF7E67';
      return <div className="men-canvas" style={{
        flexDirection: 'column',
        gap: '20px'
      }}>
          <svg width="220" height="160" style={{
          overflow: 'visible'
        }}>
            <line x1={cx} y1={cy} x2={cx + r} y2={cy} stroke="#988D84" strokeWidth="4.5" strokeLinecap="round" />
            <line x1={cx} y1={cy} x2={x2} y2={y2} stroke="#F08C46" strokeWidth="4.5" strokeLinecap="round" />
            <path d={`M ${cx + arcR} ${cy} A ${arcR} ${arcR} 0 ${largeArc} 0 ${ax} ${ay}`} fill="none" stroke={arcColor} strokeWidth="5" />
            <text x={cx + arcR + 20} y={cy - 16} fill={arcColor} fontWeight="bold" fontSize="28">{deg}°</text>
            {deg === 90 && <rect x={cx} y={cy - 20} width="20" height="20" fill="none" stroke="#4ECDC4" strokeWidth="3" />}
            <circle cx={cx} cy={cy} r="5" fill="#2D3748" />
          </svg>
          <div className="men-options-grid" style={{
          gridTemplateColumns: 'repeat(3, 1fr)',
          maxWidth: '400px'
        }}>
            {q.options?.map(opt => {
            const icons = {
              Acute: '🔺',
              Right: '📐',
              Obtuse: '🔻'
            };
            return <button key={opt} className={`men-choice-btn ${ans === opt ? 'selected' : ''}`} onClick={() => !revealed && setAns(opt)} disabled={revealed}>
                  {icons[opt]} {opt}{revealed && opt === q.answer && <span className="men-correct-tick"> ✓</span>}
                </button>;
          })}
          </div>
        </div>;
    }

    // ── CIRCLE ─────────────────────────────────────────────────────────────
    if (q.template === 'circle_q') {
      const r = q.radius;
      const rPx = Math.min(55, 160 / (r * 2 + 4)) * r;
      const cx = 110;
      const cy = 110;
      return <div className="men-canvas" style={{
        flexDirection: 'column',
        gap: '20px'
      }}>
          <svg width="220" height="220" style={{
          overflow: 'visible'
        }}>
            <defs>
              <radialGradient id="circGrd" cx="40%" cy="35%">
                <stop offset="0%" stopColor="#ffaa7b" /><stop offset="100%" stopColor="#e8864a" />
              </radialGradient>
            </defs>
            <circle cx={cx} cy={cy} r={rPx} fill="url(#circGrd)" opacity="0.85" />
            <line x1={cx} y1={cy} x2={cx + rPx} y2={cy} stroke="white" strokeWidth="2.5" strokeDasharray="6 3" />
            <text x={cx + rPx / 2} y={cy - 8} textAnchor="middle" fill="white" fontWeight="bold" fontSize="14">r={r}</text>
            <circle cx={cx} cy={cy} r="5" fill="white" />
            {q.subtype === 'circumference' && <circle cx={cx} cy={cy} r={rPx + 8} fill="none" stroke="#FDA085" strokeWidth="3" strokeDasharray="15 8" className="men-circle-spin" />}
          </svg>
          <div className="men-options-grid">
            {q.options?.map(opt => <button key={opt} className={`men-choice-btn ${ans === opt ? 'selected' : ''}`} onClick={() => !revealed && setAns(opt)} disabled={revealed}>
                {opt}{revealed && String(opt) === String(q.answer) && <span className="men-correct-tick"> ✓</span>}
              </button>)}
          </div>
        </div>;
    }

    // ── MISSING SIDE ───────────────────────────────────────────────────────
    if (q.template === 'missing_side') {
      return <div className="men-canvas" style={{
        flexDirection: 'column',
        gap: '20px'
      }}>
          {q.subtype === 'rect_missing' ? <svg width="180" height="140" style={{
          overflow: 'visible'
        }}>
              <defs>
                <linearGradient id="misGrd" x1="0%" y1="0%" x2="100%" y2="100%">
                  <stop offset="0%" stopColor="#F6D365" /><stop offset="100%" stopColor="#FDA085" />
                </linearGradient>
              </defs>
              <rect x="20" y="20" width="140" height="100" fill="url(#misGrd)" rx="8" opacity="0.8" />
              <text x="90" y="75" textAnchor="middle" fill="white" fontWeight="bold" fontSize="18">Area={q.area}</text>
              <text x="90" y="12" textAnchor="middle" fill="#FF7E67" fontWeight="bold" fontSize="16">? units</text>
              {/* Rectangle Known Side Label */}
              <text x="172" y="75" textAnchor="middle" fill="#E2E8F0" fontWeight="bold" fontSize="16" style={{
            textShadow: '0 2px 4px rgba(0,0,0,0.6)'
          }}>{q.knownSide}</text>
            </svg> : <svg width="140" height="140" style={{
          overflow: 'visible'
        }}>
              <rect x="20" y="20" width="100" height="100" fill="none" stroke="#e8864a" strokeWidth="3" strokeDasharray="8 4" rx="6" />
              {[['70', '12'], ['133', '75'], ['70', '133'], ['7', '75']].map(([x, y], i) => <g key={i}>
                  <circle cx={x} cy={parseInt(y) - 4} r="10" fill="#2D2520" stroke="#4A4038" strokeWidth="1" />
                  <text x={x} y={y} textAnchor="middle" fill="#FF7E67" fontWeight="bold" fontSize="13">?</text>
                </g>)}
              {/* Square Perimeter Label Pill */}
              <rect x="34" y="67" width="72" height="22" rx="6" fill="#2D2520" stroke="#4A4038" strokeWidth="1.5" />
              <text x="70" y="83" textAnchor="middle" fill="#F4F1ED" fontWeight="bold" fontSize="13">P={q.perim}</text>
            </svg>}
          <div className="men-options-grid">
            {q.options?.map(opt => <button key={opt} className={`men-choice-btn ${ans === opt ? 'selected' : ''}`} onClick={() => !revealed && setAns(opt)} disabled={revealed}>
                {opt}{revealed && String(opt) === String(q.answer) && <span className="men-correct-tick"> ✓</span>}
              </button>)}
          </div>
        </div>;
    }
    return null;
  };
  return <GenericLabApp title="Mensuration" subtitle="Geometry & Shape Puzzles" endpoint="/api/mensuration-lab" onBack={onBack} renderQuestionCustom={renderCustom} initialDifficulty={initialDifficulty} initialNumQuestions={initialNumQuestions} initialStarted={initialStarted} />;
}
export function getLocalXp() {
  try {
    const val = localStorage.getItem('tenali_xp');
    return val ? parseInt(val, 10) : 0;
  } catch {
    return 0;
  }
}
export function setLocalXp(val) {
  try {
    localStorage.setItem('tenali_xp', val.toString());
  } catch {}
  // dispatch event to sync UI if needed
  window.dispatchEvent(new CustomEvent('tenali_xp_update', {
    detail: {
      xp: val
    }
  }));
}
export default App;
export { AuthMenu };